  ('Business Studies', 'Edexcel', 'alevel', '2.2', 'Financial Planning', 'What is an adverse variance?', 'When actual results are worse than budgeted, e.g. lower revenue or higher costs.', 22),
  ('Business Studies', 'Edexcel', 'alevel', '2.3', 'Managing Finance', 'What is gross profit?', 'Sales revenue − cost of sales.', 1),
  ('Business Studies', 'Edexcel', 'alevel', '2.3', 'Managing Finance', 'What is operating profit?', 'Gross profit − operating expenses.', 2),
