  ('Business Studies', 'Edexcel', 'alevel', '2.4', 'Resource Management', 'What is capital-intensive production?', 'Production using mainly machinery and technology.', 8),
  ('Business Studies', 'Edexcel', 'alevel', '2.4', 'Resource Management', 'What is the capacity utilisation formula?', '(Current output ÷ maximum possible output) × 100.', 9),
  ('Business Studies', 'Edexcel', 'alevel', '2.4', 'Resource Management', 'What are the problems of high capacity utilisation?', 'Pressure on staff, no time for maintenance, and inability to meet extra orders.', 10),
