WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is the basic economic problem?', 'Scarcity: unlimited wants but finite resources, so choices must be made.', 1),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What are the four factors of production?', 'Land, labour, capital and enterprise.', 2),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is specialisation?', 'Individuals, firms or countries concentrating on producing a limited range of goods or services in which they are efficient.', 3),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What are the functions of money?', 'Medium of exchange, store of value, unit of account, and standard of deferred payment.', 4),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is a free market economy?', 'An economy where resources are allocated by the price mechanism, with minimal government intervention.', 5),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What does a shift in the PPF outwards represent?', 'Economic growth: an increase in the productive potential of the economy.', 6),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What does a demand curve show?', 'The quantity consumers are willing and able to buy at each price, ceteris paribus.', 7),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is the diminishing marginal utility explanation of demand?', 'Each extra unit gives less satisfaction, so consumers are only willing to buy more at lower prices.', 8),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What causes a supply curve to shift right?', 'Lower costs of production, improved technology, subsidies, more firms or favourable weather.', 9),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is the signalling function of price?', 'Price changes send information to producers and consumers about where resources are needed.', 10),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is the incentive function of price?', 'Higher prices encourage producers to supply more, because more profit can be made.', 11),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is the incidence of an indirect tax when demand is elastic?', 'Most of the tax is borne by producers, as they cannot pass it on without a large fall in quantity demanded.', 12),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is a subsidy?', 'A payment from the government to producers that lowers their costs, increasing supply and lowering price.', 13),
  ('Economics', 'Edexcel A', 'alevel', '1.1', 'Nature of Economics & Markets', 'What is the difference between an ad valorem and a specific tax?', 'Ad valorem is a percentage of the price (e.g. VAT); specific is a fixed amount per unit (e.g. fuel duty).', 14),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'Why do negative externalities lead to overproduction?', 'Producers only consider private costs, so output is higher than the socially optimal level where MSC = MSB.', 1),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is marginal social cost?', 'The cost to society of producing one more unit: marginal private cost plus marginal external cost.', 2),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is marginal social benefit?', 'The benefit to society of consuming one more unit: marginal private benefit plus marginal external benefit.', 3),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is a merit good?', 'A good that is underconsumed in a free market because consumers underestimate its benefits, e.g. education and healthcare.', 4),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is a demerit good?', 'A good that is overconsumed because consumers underestimate its harm, e.g. cigarettes and alcohol.', 5),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is a public good?', 'A good that is non-excludable and non-rival, e.g. street lighting and national defence.', 6),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is non-excludability?', 'It is impossible to prevent people who don''t pay from consuming the good.', 7),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is non-rivalry?', 'One person''s consumption doesn''t reduce the amount available to others.', 8),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is asymmetric information?', 'When one party in a transaction has more information than the other, e.g. used car sellers.', 9),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What are the problems of a minimum price for alcohol?', 'It may be regressive, encourage illegal sales, and doesn''t target heavy drinkers specifically.', 10),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What are the problems of a maximum price?', 'Shortages, black markets, and reduced supply over time, e.g. rent controls.', 11),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What are the causes of government failure?', 'Distortion of price signals, unintended consequences, excessive administrative costs, and information gaps.', 12),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is regulatory capture?', 'When regulators act in the interests of the industry they regulate rather than the public.', 13),
  ('Economics', 'Edexcel A', 'alevel', '1.2', 'Market Failure & Government Intervention', 'What is the Coase theorem?', 'If property rights are clearly defined and transaction costs are low, private bargaining can solve externalities.', 14),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is economic growth?', 'An increase in real GDP over time.', 1),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the difference between GDP and GNI?', 'GNI = GDP + net income from abroad.', 2),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is inflation?', 'A sustained increase in the general price level.', 3),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is deflation?', 'A sustained fall in the general price level.', 4),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the RPI?', 'The Retail Prices Index: a measure of inflation that includes housing costs such as mortgage interest payments.', 5),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the difference between CPI and RPI?', 'RPI includes housing costs and uses an arithmetic mean; CPI excludes most housing costs and uses a geometric mean.', 6),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What are the costs of unemployment to the government?', 'Lower tax revenue and higher spending on benefits.', 7),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the employment rate?', 'The proportion of the working-age population who are employed.', 8),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the balance of trade?', 'The difference between the value of exports and imports of goods and services.', 9),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the average propensity to consume?', 'Total consumption divided by total income.', 10),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the marginal propensity to save?', 'The proportion of extra income that is saved.', 11),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What is the relationship between consumer confidence and consumption?', 'Higher confidence encourages spending and borrowing; low confidence increases saving.', 12),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What are the influences on government spending?', 'The trade cycle, fiscal policy, and demographic factors.', 13),
  ('Economics', 'Edexcel A', 'alevel', '2.1', 'Economic Performance & AD', 'What influences net exports?', 'Real income at home and abroad, exchange rates, relative inflation rates, and non-price competitiveness.', 14),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is the short-run aggregate supply curve?', 'A curve showing the output firms produce at each price level when factor prices are fixed.', 1),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is long-run aggregate supply?', 'The productive potential of the economy when all factors of production are fully employed.', 2),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is the Keynesian AS curve?', 'A curve that is horizontal at low output (spare capacity), upward-sloping as capacity is approached, and vertical at full capacity.', 3),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is an injection?', 'Spending that adds to the circular flow: investment, government spending and exports.', 4),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is a withdrawal?', 'Income that leaves the circular flow: saving, taxation and imports.', 5),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is the multiplier effect?', 'An initial change in spending leads to a larger final change in national income.', 6),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is the formula for the multiplier?', '1/(1 − MPC), or 1/MPW.', 7),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is the accelerator?', 'Investment depends on the rate of change of national income; small changes in income cause large changes in investment.', 8),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is the output gap?', 'The difference between actual and potential output.', 9),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What are the conflicts between policy objectives?', 'E.g. reducing unemployment may increase inflation; faster growth may worsen the current account.', 10),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What are the limitations of monetary policy?', 'Time lags, low confidence limiting the effect of lower rates, and interest rates close to zero.', 11),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What is a fiscal deficit?', 'When government spending exceeds tax revenue in a given year.', 12),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What are market-based supply-side policies?', 'Policies that reduce government intervention, e.g. tax cuts, deregulation and privatisation.', 13),
  ('Economics', 'Edexcel A', 'alevel', '2.2', 'AS, National Income & Macro Policy', 'What are interventionist supply-side policies?', 'Government investment in education, training, infrastructure and R&D.', 14),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is a public sector organisation?', 'An organisation owned and controlled by the government, e.g. the NHS.', 1),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is a not-for-profit organisation?', 'An organisation that reinvests surplus revenue to achieve its social goals, e.g. charities.', 2),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is a merger?', 'Two firms agreeing to combine into one.', 3),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is a takeover?', 'One firm buying a controlling interest in another.', 4),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is backward vertical integration?', 'Merging with a firm at an earlier stage of production, e.g. a car maker buying a steel producer.', 5),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is forward vertical integration?', 'Merging with a firm at a later stage of production, e.g. a manufacturer buying a retailer.', 6),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is a conglomerate merger?', 'A merger between firms in unrelated industries, spreading risk.', 7),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is demerger?', 'Splitting a firm into separate companies, often to focus on core activities or improve efficiency.', 8),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What are the constraints on business growth?', 'Size of the market, access to finance, and owner objectives.', 9),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is revenue maximisation?', 'Producing where MR = 0, which maximises total revenue.', 10),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is sales maximisation?', 'Producing the largest output possible while still making normal profit (where AC = AR).', 11),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is satisficing?', 'Aiming to achieve satisfactory rather than maximum profits, to satisfy different stakeholders.', 12),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'Why might managers pursue revenue maximisation?', 'Their salaries and status are often linked to the size of the firm.', 13),
  ('Economics', 'Edexcel A', 'alevel', '3.1', 'Business Growth & Objectives', 'What is shut-down in the long run?', 'A firm leaves the industry if price is below average total cost.', 14),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is perfect competition?', 'Many buyers and sellers, identical products, perfect information and no barriers to entry or exit.', 1),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'Why do perfectly competitive firms make normal profit in the long run?', 'Supernormal profits attract new firms, increasing supply and lowering price until only normal profit is made.', 2),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is allocative efficiency?', 'Producing where price equals marginal cost, so resources match consumer preferences.', 3),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is productive efficiency?', 'Producing at the lowest point on the average cost curve.', 4),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is interdependence in oligopoly?', 'Each firm''s decisions depend on how rivals are expected to react.', 5),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is price leadership?', 'One dominant firm sets the price and others follow.', 6),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is a price war?', 'Firms repeatedly cut prices to gain market share, reducing profits for all.', 7),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What are the advantages of monopoly?', 'Economies of scale, and supernormal profits that can fund research and development.', 8),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What are the disadvantages of monopoly?', 'Higher prices, lower output, less choice, and allocative and productive inefficiency.', 9),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is monopsony?', 'A market with a single buyer, e.g. the NHS as a buyer of drugs.', 10),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What are the effects of monopsony power on suppliers?', 'Lower prices paid to suppliers, which reduces their profits.', 11),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is wage elasticity of demand for labour?', 'The responsiveness of labour demand to a change in the wage rate.', 12),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is the impact of a national minimum wage?', 'It may raise incomes of low-paid workers but could reduce employment if set above equilibrium in a competitive market.', 13),
  ('Economics', 'Edexcel A', 'alevel', '3.2', 'Market Structures & Labour', 'What is the role of the Competition and Markets Authority?', 'It investigates mergers and anti-competitive behaviour, and enforces competition law.', 14),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is globalisation?', 'The increasing integration and interdependence of economies around the world.', 1),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What are the causes of globalisation?', 'Improvements in transport and communication, trade liberalisation, and the growth of MNCs.', 2),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is a trading bloc?', 'A group of countries that agree to reduce trade barriers between them.', 3),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is trade creation?', 'When joining a trading bloc leads to a shift from high-cost domestic producers to lower-cost producers within the bloc.', 4),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is trade diversion?', 'When joining a trading bloc leads to a shift from low-cost producers outside the bloc to higher-cost producers inside it.', 5),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is a quota?', 'A physical limit on the quantity of a good that can be imported.', 6),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is an export subsidy?', 'A payment to domestic exporters to make their goods cheaper abroad.', 7),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What are non-tariff barriers?', 'Regulations, standards and administrative procedures that restrict imports.', 8),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is the J-curve effect?', 'After a depreciation, the current account initially worsens before improving, as demand for exports and imports is initially inelastic.', 9),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is a managed exchange rate?', 'A floating exchange rate where the central bank intervenes to influence its value.', 10),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is devaluation?', 'A deliberate reduction in the value of a currency in a fixed exchange rate system.', 11),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What factors affect international competitiveness?', 'Exchange rates, relative productivity, labour costs, inflation, and non-price factors like quality.', 12),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What is unit labour cost?', 'The cost of labour per unit of output.', 13),
  ('Economics', 'Edexcel A', 'alevel', '4.1', 'International Economics & Trade', 'What are the benefits of FDI to a host country?', 'Jobs, technology transfer, higher tax revenue, and improved skills.', 14),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is absolute poverty?', 'When income is insufficient to meet basic needs such as food, shelter and clothing.', 1),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is relative poverty?', 'Having an income below a certain proportion (usually 60%) of median income.', 2),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What are the causes of changes in absolute poverty?', 'Economic growth, changes in employment, and government policies.', 3),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is inequality of wealth?', 'Unequal distribution of assets such as property, savings and shares.', 4),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What are the impacts of economic change on inequality?', 'Globalisation and technological change can increase wage differences between skilled and unskilled workers.', 5),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is the Kuznets curve?', 'The idea that inequality first rises then falls as an economy develops.', 6),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What are the primary product dependency problems?', 'Volatile prices, low income elasticity of demand, and the Prebisch–Singer hypothesis of declining terms of trade.', 7),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is the savings gap?', 'The shortfall between savings and the investment needed for development, as in the Harrod–Domar model.', 8),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is capital flight?', 'When wealth and capital leave a country, often due to instability or poor returns.', 9),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is corruption''s effect on development?', 'It diverts resources, discourages investment, and reduces trust in institutions.', 10),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What are the market-orientated strategies for development?', 'Trade liberalisation, promotion of FDI, removing subsidies, and floating exchange rates.', 11),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What are the interventionist strategies for development?', 'Developing human capital, protectionism, managed exchange rates, infrastructure and joint ventures.', 12),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is debt relief?', 'Cancelling or reducing the debts of developing countries so resources can be used for development.', 13),
  ('Economics', 'Edexcel A', 'alevel', '4.2', 'Poverty, Inequality & Development', 'What is the role of NGOs in development?', 'Non-governmental organisations provide aid, expertise and advocacy, often focusing on grassroots projects.', 14)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Economics' AND exam_board = 'Edexcel A' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

