WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What are the language levels (frameworks) used in analysis?', 'Phonetics/phonology/prosody, lexis and semantics, grammar (including morphology), pragmatics, discourse, and graphology.', 1),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is lexis?', 'The vocabulary of a language or text.', 2),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is semantics?', 'The study of meaning in words and phrases.', 3),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is grammar?', 'The rules governing how words are formed and combined into sentences, including morphology and syntax.', 4),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is morphology?', 'The study of the structure of words and how they are formed from morphemes.', 5),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a morpheme?', 'The smallest unit of meaning, e.g. "un-", "happy", "-ness".', 6),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is syntax?', 'The arrangement of words into phrases, clauses and sentences.', 7),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is pragmatics?', 'The study of implied meaning and how context affects interpretation.', 8),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is discourse?', 'The structure and organisation of a text beyond the sentence level.', 9),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is graphology?', 'The visual aspects of a text, such as layout, typography, images and colour.', 10),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is phonology?', 'The study of the sound system of a language.', 11),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is prosody?', 'Features of speech such as intonation, stress, pitch, tempo and volume.', 12),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a noun phrase?', 'A group of words with a noun as the head, e.g. "the old red car".', 13),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a pre-modifier?', 'A word placed before the head noun to add detail, e.g. "red" in "red car".', 14),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a post-modifier?', 'A word or phrase placed after the head noun, e.g. "in the garden" in "the man in the garden".', 15),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a declarative sentence?', 'A sentence that makes a statement.', 16),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is an interrogative sentence?', 'A sentence that asks a question.', 17),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is an imperative sentence?', 'A sentence that gives a command.', 18),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is an exclamative sentence?', 'A sentence that expresses strong emotion, often beginning with "what" or "how".', 19),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a simple sentence?', 'A sentence with one independent clause.', 20),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a compound sentence?', 'A sentence with two or more independent clauses joined by a coordinating conjunction.', 21),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a complex sentence?', 'A sentence with an independent clause and at least one subordinate clause.', 22),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is modality?', 'The expression of possibility, necessity or obligation, often using modal verbs such as "might", "must", "should".', 23),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is register?', 'The level of formality in language, adjusted to suit the audience and context.', 24),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is a semantic field?', 'A group of words related in meaning, e.g. "doctor, nurse, ward" (hospital).', 25),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is connotation?', 'The associations or emotional meanings attached to a word beyond its literal meaning.', 26),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is denotation?', 'The literal, dictionary meaning of a word.', 27),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is deixis?', 'Words whose meaning depends on context, e.g. "here", "there", "now", "this".', 28),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is ellipsis?', 'Omitting words that can be understood from context.', 29),
  ('English Language', 'AQA', 'alevel', '1.1', 'Methods of Language Analysis', 'What is cohesion?', 'The ways a text is linked together, e.g. through pronouns, connectives and lexical repetition.', 30),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is representation?', 'The way language portrays people, places, events and ideas, shaping how the audience perceives them.', 1),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is mode?', 'Whether a text is spoken, written or multimodal (e.g. electronic).', 2),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is genre?', 'A category of text with shared conventions, e.g. news report or advert.', 3),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is audience?', 'The intended readers or listeners of a text.', 4),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is purpose?', 'The aim of a text, e.g. to inform, persuade, entertain or instruct.', 5),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is context of production?', 'The circumstances in which a text is created.', 6),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is context of reception?', 'The circumstances in which a text is read or heard.', 7),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a multimodal text?', 'A text that combines different modes, such as written language, images and sound.', 8),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a synthetic personalisation?', 'Addressing a mass audience as if they were individuals, e.g. using "you" (Fairclough).', 9),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is direct address?', 'Speaking directly to the reader, often using second-person pronouns.', 10),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a persona?', 'The identity or voice a writer creates in a text.', 11),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is foregrounding?', 'Making certain information prominent, e.g. by placing it first.', 12),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is agency?', 'Who is shown as responsible for an action in a sentence.', 13),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'How does the passive voice affect representation?', 'It can hide or downplay the agent, e.g. "mistakes were made".', 14),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is nominalisation?', 'Turning a verb or adjective into a noun, e.g. "decide" → "decision", often making a text more formal or abstract.', 15),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a rhetorical question?', 'A question asked for effect rather than for an answer.', 16),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is the rule of three?', 'Grouping ideas in threes for emphasis and memorability.', 17),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is hyperbole?', 'Deliberate exaggeration for effect.', 18),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is euphemism?', 'A mild or indirect word used in place of one that may be harsh or offensive.', 19),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is dysphemism?', 'A harsh or offensive word used instead of a neutral one.', 20),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is face (politeness theory)?', 'A person''s public self-image: positive face (wanting to be liked) and negative face (wanting freedom from imposition).', 21),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a face-threatening act?', 'An act that challenges someone''s positive or negative face.', 22),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is Grice''s cooperative principle?', 'Speakers follow maxims of quantity, quality, relation and manner to communicate effectively.', 23),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is flouting a maxim?', 'Deliberately breaking a maxim to imply meaning, e.g. sarcasm.', 24),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a discourse marker?', 'A word or phrase that organises speech or writing, e.g. "so", "anyway", "however".', 25),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is an adjacency pair?', 'Two related utterances by different speakers, e.g. question and answer.', 26),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is phatic talk?', 'Small talk used for social purposes rather than information, e.g. "Nice weather".', 27),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is non-fluency?', 'Features of spontaneous speech such as fillers, pauses, false starts and repairs.', 28),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is a filler?', 'A sound or word used to fill a pause, e.g. "um", "er", "like".', 29),
  ('English Language', 'AQA', 'alevel', '1.2', 'Textual Variations and Representations', 'What is intertextuality?', 'References to other texts within a text.', 30),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What are the stages of children''s spoken language development?', 'Pre-verbal (cooing, babbling), holophrastic, two-word, telegraphic, and post-telegraphic.', 1),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is cooing?', 'Early vowel-like sounds made by babies from about 6–8 weeks.', 2),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is babbling?', 'Repeated consonant–vowel combinations, e.g. "bababa", from about 6 months.', 3),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is the holophrastic stage?', 'Around 12–18 months, when children use single words to express whole ideas.', 4),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is the two-word stage?', 'Around 18–24 months, when children combine two words, e.g. "daddy go".', 5),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is the telegraphic stage?', 'Around 24–36 months, when children use short phrases with mainly content words, omitting function words.', 6),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is overextension?', 'Using a word too broadly, e.g. calling all animals "dog".', 7),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is underextension?', 'Using a word too narrowly, e.g. using "cat" only for the family cat.', 8),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is a virtuous error?', 'A mistake that shows a child is applying a grammar rule logically, e.g. "I goed".', 9),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is overgeneralisation?', 'Applying a rule too widely, e.g. adding "-s" to make "mouses".', 10),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Skinner''s theory?', 'Behaviourism: children learn language through imitation and reinforcement.', 11),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Chomsky''s theory?', 'Nativism: children have an innate Language Acquisition Device (LAD) that enables them to learn language.', 12),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Piaget''s theory?', 'Cognitive theory: language develops as children''s thinking develops.', 13),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Bruner''s theory?', 'Interactionism: children learn through interaction with caregivers, supported by a Language Acquisition Support System (LASS).', 14),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is child-directed speech (CDS)?', 'The way adults speak to young children: simplified vocabulary, repetition, higher pitch and exaggerated intonation.', 15),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is scaffolding?', 'Support given by adults to help children achieve what they can''t yet do alone.', 16),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is the critical period hypothesis?', 'The idea that there is a window in childhood when language must be acquired.', 17),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What does the case of Genie suggest?', 'Genie was deprived of language until 13 and never fully acquired grammar, supporting the critical period hypothesis.', 18),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s instrumental function?', 'Language used to get things, e.g. "I want".', 19),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s regulatory function?', 'Language used to control others'' behaviour.', 20),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s interactional function?', 'Language used to form relationships.', 21),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s personal function?', 'Language used to express feelings and identity.', 22),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s heuristic function?', 'Language used to learn about the environment, e.g. asking questions.', 23),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s imaginative function?', 'Language used for play and storytelling.', 24),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Halliday''s representational function?', 'Language used to convey information.', 25),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is phonological development?', 'How children learn to produce the sounds of their language.', 26),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is deletion in phonological development?', 'Omitting sounds, e.g. "nana" for "banana".', 27),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is substitution in phonological development?', 'Replacing one sound with an easier one, e.g. "wabbit" for "rabbit".', 28),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is consonant cluster reduction?', 'Simplifying clusters, e.g. "pider" for "spider".', 29),
  ('English Language', 'AQA', 'alevel', '1.3', 'Children''s Spoken Language Development', 'What is Brown''s order of morpheme acquisition?', 'The order in which children acquire grammatical morphemes, e.g. "-ing" first, then plural "-s", then possessive "''s".', 30),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What are the stages of children''s written development?', 'Kroll''s stages: preparation, consolidation, differentiation and integration.', 1),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is Kroll''s preparation stage?', 'Up to about 6 years: learning motor skills and basic spelling.', 2),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is Kroll''s consolidation stage?', 'About 7–8 years: writing like speaking, with simple sentences and "and" as the main conjunction.', 3),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is Kroll''s differentiation stage?', 'About 9–10 years: understanding differences between speech and writing, and using genre conventions.', 4),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is Kroll''s integration stage?', 'Mid-teens onwards: developing a personal voice and control of style.', 5),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What are Barclay''s stages of writing?', 'Scribbling, mock handwriting, mock letters, conventional letters, invented spelling, appropriate spelling, and correct spelling.', 6),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is Rothery''s categorisation of children''s writing?', 'Observation/comment, recount, report and narrative.', 7),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is phonetic spelling?', 'Spelling words as they sound, e.g. "sed" for "said".', 8),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is insertion in spelling?', 'Adding extra letters, e.g. "whent" for "went".', 9),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is omission in spelling?', 'Leaving out letters, e.g. "wich" for "which".', 10),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is transposition in spelling?', 'Reversing letters, e.g. "form" for "from".', 11),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is overgeneralisation in spelling?', 'Applying a spelling rule incorrectly, e.g. "happyly".', 12),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is a homophone error?', 'Using the wrong word with the same sound, e.g. "there" for "their".', 13),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is synthetic phonics?', 'Teaching reading by blending individual letter sounds to form words.', 14),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is the whole-word (look and say) approach?', 'Teaching children to recognise whole words by sight.', 15),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is emergent literacy?', 'The early reading and writing skills children develop before formal teaching.', 16),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What does Clay''s research show about writing?', 'Children understand concepts such as directionality and spacing gradually.', 17),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is the role of reading in writing development?', 'Exposure to texts helps children learn vocabulary, spelling and genre conventions.', 18),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What are features of early narrative writing?', 'Simple chronology, first-person perspective, repetition of "and then", and limited description.', 19),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'How do children''s texts show developing cohesion?', 'Increasing use of pronouns, connectives and varied sentence openings.', 20),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is the role of the teacher''s feedback?', 'It helps children correct errors and develop their writing.', 21),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is a genre convention?', 'An expected feature of a type of text, e.g. "Once upon a time" in stories.', 22),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What does increasing sentence complexity show?', 'Growing grammatical knowledge, such as subordination and embedded clauses.', 23),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is the difference between spoken and written language for children?', 'Early writing mirrors speech; children gradually learn more formal written structures.', 24),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'How does technology affect children''s literacy?', 'Texting and digital media may develop phonological awareness and creativity; there are debates over its effect on spelling.', 25),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What did Plester''s research find about texting?', 'Children who used more textisms often had better phonological awareness and literacy.', 26),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is handwriting development?', 'From scribbles to letter formation, then joined and fluent writing.', 27),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is metalinguistic awareness?', 'The ability to think and talk about language itself.', 28),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is Kress''s theory on children''s writing?', 'Children''s writing develops as they learn the differences between speech and writing, and use conventions.', 29),
  ('English Language', 'AQA', 'alevel', '1.4', 'Children''s Written Language Development', 'What is punctuation development?', 'Children learn full stops and capitals first, then commas, speech marks and more complex punctuation.', 30),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is a dialect?', 'A variety of language with distinctive vocabulary and grammar, linked to region or social group.', 1),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is an accent?', 'A distinctive way of pronouncing words, linked to region or social group.', 2),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Standard English?', 'The prestige variety of English used in formal writing and education, not tied to a region.', 3),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Received Pronunciation (RP)?', 'A prestige accent traditionally associated with the upper and middle classes.', 4),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is a sociolect?', 'A variety of language used by a particular social group.', 5),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is an idiolect?', 'An individual''s personal way of using language.', 6),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is covert prestige?', 'Status gained by using non-standard language within a group.', 7),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is overt prestige?', 'Status gained by using standard, socially recognised language.', 8),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Labov''s Martha''s Vineyard study?', 'Locals exaggerated their accent to show identity and distinguish themselves from tourists.', 9),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Labov''s department store study?', 'Pronunciation of post-vocalic /r/ varied with social class of the store.', 10),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Trudgill''s Norwich study?', 'Men used non-standard forms more than women, linked to covert prestige.', 11),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Milroy''s Belfast study?', 'People in close-knit social networks used more local, non-standard features.', 12),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is dialect levelling?', 'The reduction of differences between regional dialects.', 13),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Estuary English?', 'An accent spreading from the south-east of England, combining features of RP and London accents.', 14),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is Multicultural London English (MLE)?', 'A variety of English spoken by young people in London, influenced by many languages.', 15),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What are features of MLE?', 'Words like "innit", "bare", "man" as a pronoun, and "this is me" as a quotative.', 16),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is code-switching?', 'Switching between languages or varieties in a conversation.', 17),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is accommodation theory?', 'Speakers adjust their speech to converge with or diverge from others (Giles).', 18),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is convergence?', 'Adapting speech to become more similar to the listener''s.', 19),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is divergence?', 'Emphasising differences in speech from the listener''s.', 20),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is an occupational register?', 'Specialised language used in a particular job, e.g. medical jargon.', 21),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is jargon?', 'Specialised terminology used by a particular group.', 22),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is slang?', 'Informal words or phrases, often used by particular groups.', 23),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is a communities of practice?', 'Groups of people who share interests and develop distinctive ways of speaking (Eckert).', 24),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is audience design?', 'Bell''s theory that speakers adjust their style for their audience.', 25),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is the Queen''s English study?', 'Harrington showed that the Queen''s accent changed over time, becoming less "posh".', 26),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is a non-standard grammatical feature?', 'E.g. double negatives ("I didn''t do nothing") or "we was".', 27),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is linguistic prejudice?', 'Negative attitudes towards people based on their accent or dialect.', 28),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is h-dropping?', 'Omitting the /h/ sound at the start of words, e.g. "''ouse".', 29),
  ('English Language', 'AQA', 'alevel', '2.1', 'Language Diversity (Regional & Social)', 'What is glottal stopping?', 'Replacing /t/ with a glottal stop, e.g. "wa''er" for "water".', 30),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the deficit model of gender and language?', 'Lakoff''s view that women''s language is weaker and less assertive than men''s.', 1),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What features did Lakoff identify in women''s speech?', 'Hedges, tag questions, empty adjectives, super-polite forms and intensifiers.', 2),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the dominance model?', 'Zimmerman and West''s view that men dominate conversation, e.g. through interruptions.', 3),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What did Zimmerman and West find?', 'In mixed-sex conversations, men made most of the interruptions.', 4),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the difference model?', 'Tannen''s view that men and women have different conversational styles.', 5),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What are Tannen''s six contrasts?', 'Status/support, independence/intimacy, advice/understanding, information/feelings, orders/proposals, conflict/compromise.', 6),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the diversity model?', 'The view that gender is one of many factors affecting language, and variation within genders is greater than between them.', 7),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What did Cameron argue?', 'Differences in language are due to context and power rather than gender; she challenged the "myth of Mars and Venus".', 8),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is Butler''s theory of gender performativity?', 'Gender is something we perform through repeated behaviour, including language.', 9),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is a hedge?', 'A word or phrase that softens a statement, e.g. "sort of", "maybe".', 10),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is a tag question?', 'A question added to a statement, e.g. "It''s cold, isn''t it?"', 11),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What did Holmes find about tag questions?', 'Women often used tag questions to facilitate conversation, not due to uncertainty.', 12),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What did Fishman find?', 'Women did more "conversational shitwork", asking questions to keep conversations going.', 13),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is sexist language?', 'Language that discriminates or stereotypes based on gender, e.g. "fireman".', 14),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is semantic derogation?', 'When words associated with women develop negative meanings over time, e.g. "mistress".', 15),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the generic "he"?', 'Using "he" to refer to people in general, now seen as exclusive.', 16),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is marked language?', 'Adding a gender marker to show difference from the norm, e.g. "female doctor".', 17),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What are gender-neutral terms?', 'Words that don''t specify gender, e.g. "firefighter" or "chair".', 18),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is singular "they"?', 'Using "they" to refer to one person of unknown or non-binary gender.', 19),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'How is gender represented in the media?', 'Through stereotypical language, e.g. focusing on women''s appearance.', 20),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is lexical asymmetry?', 'Unequal pairs of words, e.g. "bachelor" (positive) versus "spinster" (negative).', 21),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What did Coates find about all-female talk?', 'Women used cooperative strategies such as minimal responses and overlapping speech.', 22),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is a minimal response?', 'Short responses like "mm" or "yeah" to show listening.', 23),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What did Beattie find about interruptions?', 'Women interrupted as much as men, challenging the dominance model.', 24),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is Jespersen''s view of women''s language?', 'An early, stereotyped view that women''s language was inferior and less complex.', 25),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'How do gender and language interact in the workplace?', 'Power and role often affect language more than gender.', 26),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the "gendered" language in children''s toys?', 'Boys'' toys use action and power words; girls'' toys use appearance and caring words.', 27),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is political correctness in language?', 'Avoiding language that may exclude or offend groups.', 28),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is the role of social media in gendered language?', 'It allows new identities and challenges norms, but can also reinforce stereotypes.', 29),
  ('English Language', 'AQA', 'alevel', '2.2', 'Language and Gender', 'What is linguistic reform?', 'Changing language to make it less sexist, e.g. "Ms" instead of "Miss" or "Mrs".', 30),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is ethnolect?', 'A variety of language associated with an ethnic group.', 1),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is World English?', 'The varieties of English used around the world.', 2),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Kachru''s concentric circles model?', 'Inner circle (native speakers, e.g. UK), outer circle (second language, e.g. India), expanding circle (foreign language, e.g. China).', 3),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is a lingua franca?', 'A language used for communication between speakers of different languages.', 4),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'Why is English a global lingua franca?', 'Colonialism, US economic and cultural power, and its use in science, business and the internet.', 5),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is a pidgin?', 'A simplified language that develops for communication between groups without a common language.', 6),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is a creole?', 'A pidgin that has become the first language of a community, with a full grammar.', 7),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Singlish?', 'Singapore English, with influences from Malay, Chinese and Tamil.', 8),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Indian English?', 'The variety of English spoken in India, with distinctive vocabulary and grammar.', 9),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is linguistic imperialism?', 'The dominance of one language over others, often linked to colonial or economic power (Phillipson).', 10),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is language death?', 'When a language no longer has any native speakers.', 11),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Jenkins''s Lingua Franca Core?', 'Key pronunciation features needed for international intelligibility in English.', 12),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Crystal''s view of global English?', 'English will continue to spread and diversify into many varieties.', 13),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is McArthur''s circle of World English?', 'A model with World Standard English at the centre, surrounded by regional varieties.', 14),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Multicultural London English?', 'A multiethnolect spoken by young Londoners from diverse backgrounds.', 15),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is a multiethnolect?', 'A variety that develops from contact between many ethnic groups.', 16),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is crossing?', 'Using a language variety associated with a different ethnic group (Rampton).', 17),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What did Rampton''s study show?', 'Young people used features of other ethnic groups'' languages to express identity.', 18),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Kerswill''s research on MLE?', 'He found MLE was spoken by young people of all ethnicities in London.', 19),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is identity in language?', 'How language expresses who we are, including ethnicity, class and region.', 20),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What are attitudes to ethnolects?', 'Some view them negatively as "incorrect"; others see them as valid expressions of identity.', 21),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is language planning?', 'Deliberate efforts to influence language use, e.g. making a language official.', 22),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Global English''s impact on other languages?', 'Loanwords enter other languages, and some fear loss of linguistic diversity.', 23),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is code-mixing?', 'Mixing words from two languages within a sentence.', 24),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Hinglish?', 'A mix of Hindi and English used in India.', 25),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Nigerian English?', 'A variety of English spoken in Nigeria, with distinctive vocabulary and grammar.', 26),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is linguistic diversity?', 'The variety of languages and dialects in the world.', 27),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'Why do some people resist Global English?', 'To protect national languages and cultural identity, e.g. French language laws.', 28),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is the role of the internet in Global English?', 'It spreads English worldwide and creates new varieties and vocabulary.', 29),
  ('English Language', 'AQA', 'alevel', '2.3', 'Language and Ethnicity / World Englishes', 'What is Englishisation?', 'The influence of English on other languages and cultures.', 30),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is language change?', 'The ways a language develops over time in lexis, grammar, pronunciation and meaning.', 1),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is Old English?', 'English spoken from about 450 to 1100, influenced by Germanic languages.', 2),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is Middle English?', 'English spoken from about 1100 to 1500, heavily influenced by French after the Norman Conquest.', 3),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is Early Modern English?', 'English from about 1500 to 1700, the time of Shakespeare and the printing press.', 4),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is the Great Vowel Shift?', 'A major change in the pronunciation of long vowels in English, from about 1400 to 1700.', 5),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What was the impact of the printing press?', 'It helped standardise spelling and spread written English.', 6),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What was Johnson''s dictionary?', 'Samuel Johnson''s 1755 dictionary, which helped standardise spelling and meaning.', 7),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is prescriptivism?', 'The view that there are correct and incorrect forms of language that should be followed.', 8),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is descriptivism?', 'The view that linguists should describe how language is actually used, without judging it.', 9),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is neologism?', 'A newly created word or expression.', 10),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is borrowing?', 'Taking words from other languages, e.g. "café" from French.', 11),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is compounding?', 'Combining two words to create a new one, e.g. "smartphone".', 12),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is blending?', 'Combining parts of two words, e.g. "brunch" (breakfast + lunch).', 13),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is clipping?', 'Shortening a word, e.g. "phone" from "telephone".', 14),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is an acronym?', 'A word formed from initial letters and pronounced as a word, e.g. NATO.', 15),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is an initialism?', 'Initial letters pronounced separately, e.g. BBC.', 16),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is conversion?', 'Changing a word''s class without changing its form, e.g. "Google" (noun) to "to google" (verb).', 17),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is affixation?', 'Adding prefixes or suffixes to create new words, e.g. "unfriend".', 18),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is amelioration?', 'When a word''s meaning becomes more positive, e.g. "nice" (once meaning foolish).', 19),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is pejoration?', 'When a word''s meaning becomes more negative, e.g. "silly" (once meaning blessed).', 20),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is broadening?', 'When a word''s meaning becomes wider, e.g. "holiday" (holy day).', 21),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is narrowing?', 'When a word''s meaning becomes more specific, e.g. "meat" (once meaning any food).', 22),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is Aitchison''s damp spoon syndrome?', 'The view that language change is due to laziness, which Aitchison rejects.', 23),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is Aitchison''s crumbling castle view?', 'The view that language was once perfect and is decaying, which Aitchison rejects.', 24),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is Aitchison''s infectious disease view?', 'The view that bad language habits spread like a disease, which Aitchison rejects.', 25),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is the S-curve model of change?', 'Change starts slowly, spreads rapidly, then slows as it reaches most speakers.', 26),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is the wave model of change?', 'Change spreads outwards from a central point, like ripples.', 27),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is the functional theory of change?', 'Language changes to meet the needs of its users, e.g. new technology.', 28),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is random fluctuation theory?', 'Language changes randomly, without a specific cause.', 29),
  ('English Language', 'AQA', 'alevel', '2.4', 'Language Change', 'What is the effect of technology on language change?', 'New words (e.g. "selfie"), new forms of communication, and faster spread of change.', 30),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a language discourse?', 'A way of talking about language that reflects particular attitudes and ideologies.', 1),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a discourse about language change?', 'Debates about whether change represents decline or natural evolution.', 2),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a prescriptive discourse?', 'Language that argues for "correct" usage and criticises change or non-standard forms.', 3),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a descriptive discourse?', 'Language that accepts and explains variation and change without judgement.', 4),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What are typical features of a prescriptive text?', 'Emotive language, metaphors of decay, appeals to tradition, and negative representation of speakers.', 5),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What metaphors are often used about language decline?', 'Disease, decay, invasion, crime and pollution.', 6),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is linguistic purism?', 'The desire to keep a language "pure" from foreign influence or change.', 7),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a moral panic about language?', 'Exaggerated public anxiety about language change, e.g. texting ruining literacy.', 8),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is John Humphrys''s view on texting?', 'He argued texting was "vandalising" language, a prescriptive view.', 9),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is David Crystal''s view on texting?', 'He argued texting is creative and doesn''t harm literacy.', 10),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a discourse about accents?', 'Debates about attitudes to regional and social accents, often linking them to intelligence or class.', 11),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a discourse about gender and language?', 'Debates about sexist language and whether language should be reformed.', 12),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a discourse about global English?', 'Debates about English as a global language, including linguistic imperialism and loss of diversity.', 13),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'How are writers'' attitudes to language represented?', 'Through lexical choices, tone, metaphors and the way they represent speakers.', 14),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is an ideology?', 'A set of beliefs and values that shapes how people see the world.', 15),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is the role of the media in language discourses?', 'It shapes public attitudes by presenting language issues in particular ways.', 16),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a genre used in language discourse?', 'Opinion articles, letters, blogs and online comments.', 17),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a rhetorical feature of discourse texts?', 'Rhetorical questions, lists, hyperbole and emotive language.', 18),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is authority in discourse texts?', 'Writers establish credibility through expertise, quotes or experience.', 19),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is the role of the audience in discourse texts?', 'Writers appeal to readers'' values and beliefs to persuade them.', 20),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is "grammar Nazi" discourse?', 'Online criticism of others'' grammar, often prescriptive and judgemental.', 21),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is the language of standardisation discourse?', 'Arguments that Standard English is necessary for education and communication.', 22),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'How do descriptive linguists respond to prescriptivism?', 'They argue all varieties are rule-governed and valid.', 23),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is the "lexical gap" argument?', 'New words fill gaps in meaning, supporting functional views of change.', 24),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is identity in language discourse?', 'The idea that language varieties express identity and should be respected.', 25),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is linguistic insecurity?', 'When speakers feel their variety is inferior.', 26),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is the role of schools in language discourses?', 'Schools often promote Standard English, which can reinforce prescriptive attitudes.', 27),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is Lynne Truss''s view?', 'In "Eats, Shoots & Leaves" she argued for strict punctuation rules, a prescriptive view.', 28),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is Steven Pinker''s view?', 'He argues language is an instinct and all speakers use complex rules, a descriptive view.', 29),
  ('English Language', 'AQA', 'alevel', '2.5', 'Language Discourses', 'What is a counter-discourse?', 'An alternative way of talking about language that challenges dominant views.', 30),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a language investigation?', 'An independent research project analysing a language data set to explore a research question.', 1),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a research question?', 'A focused question guiding an investigation.', 2),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a hypothesis in language research?', 'A prediction about what the investigation will find.', 3),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is qualitative analysis?', 'Detailed analysis of language features and their meanings.', 4),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is quantitative analysis?', 'Analysis using numbers, e.g. frequency counts of language features.', 5),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a corpus?', 'A large collection of texts used for analysis.', 6),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is primary data?', 'Data collected by the researcher, e.g. recordings or interviews.', 7),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is secondary data?', 'Data collected by others, e.g. existing texts or corpora.', 8),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is the observer''s paradox?', 'The way people change their speech when they know they are being observed (Labov).', 9),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'How can the observer''s paradox be reduced?', 'Recording people in natural settings, over time, or without focusing on language.', 10),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What are ethical considerations in language research?', 'Obtaining consent, protecting anonymity, and avoiding harm.', 11),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is transcription?', 'Writing down spoken language, often using symbols for pauses and overlaps.', 12),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a transcription key?', 'A guide explaining the symbols used in a transcript.', 13),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is methodology?', 'The methods used to collect and analyse data.', 14),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a pilot study?', 'A small trial to test methods before the main investigation.', 15),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is sampling in language research?', 'Selecting representative data for analysis.', 16),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is the literature review?', 'A summary of existing research relevant to the investigation.', 17),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a conclusion in an investigation?', 'A summary of findings, linked back to the research question and theories.', 18),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is an evaluation?', 'A reflection on the strengths and limitations of the investigation.', 19),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'Why is it important to link findings to theory?', 'It shows understanding of how data supports or challenges existing research.', 20),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is validity in language research?', 'Whether the research measures what it claims to measure.', 21),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is reliability?', 'Whether the findings would be consistent if repeated.', 22),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is the word limit for AQA NEA?', '2000 words for the investigation (excluding data and references).', 23),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What topics can a language investigation explore?', 'E.g. gender in conversation, children''s language, language change, representation in media.', 24),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a comparative investigation?', 'Comparing two or more data sets, e.g. texts from different time periods.', 25),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What are the limitations of small data sets?', 'Results may not be representative or generalisable.', 26),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'Why is triangulation useful?', 'Using several methods or data sources makes findings more reliable.', 27),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is bias in language research?', 'When the researcher''s views or methods affect the results.', 28),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'What is a variable in language research?', 'A factor that may affect language use, e.g. age, gender or context.', 29),
  ('English Language', 'AQA', 'alevel', '3.1', 'Language Investigation (NEA)', 'How should findings be presented?', 'Clearly, with examples from the data, tables where useful, and linguistic terminology.', 30),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is original writing in the NEA?', 'A piece of creative or persuasive writing based on a style model.', 1),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a style model?', 'An existing text that provides a model of genre and style for original writing.', 2),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a commentary?', 'An analysis of the language choices made in the original writing, compared with the style model.', 3),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What genres can be used for original writing?', 'The power of persuasion, the power of storytelling, or the power of information.', 4),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is the word count for AQA original writing?', 'About 750 words for the writing and 750 for the commentary.', 5),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What should a commentary include?', 'Analysis of the writer''s choices, their effects, and comparison with the style model, using linguistic terms.', 6),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is narrative voice?', 'The perspective from which a story is told, e.g. first or third person.', 7),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is free indirect discourse?', 'A narrative technique blending the narrator''s voice with a character''s thoughts.', 8),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a hook?', 'An opening designed to grab the reader''s attention.', 9),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is pace in writing?', 'The speed at which events unfold, controlled by sentence length and detail.', 10),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a persuasive technique?', 'E.g. rhetorical questions, emotive language, statistics and direct address.', 11),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is an informative text?', 'A text designed to explain or inform, using clear structure, facts and subject-specific vocabulary.', 12),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is audience adaptation?', 'Adjusting language to suit the intended readers.', 13),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is characterisation?', 'How a writer creates and develops characters.', 14),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is dialogue in fiction?', 'Conversation between characters, used to reveal personality and advance the plot.', 15),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is imagery?', 'Descriptive language that creates pictures in the reader''s mind.', 16),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a metaphor?', 'Describing something as if it were something else.', 17),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a simile?', 'A comparison using "like" or "as".', 18),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is personification?', 'Giving human qualities to non-human things.', 19),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is structure in original writing?', 'The organisation of ideas, e.g. chronological or thematic.', 20),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a cyclical structure?', 'A text that ends where it began.', 21),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is a flashback?', 'A scene set earlier than the main story.', 22),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is register in original writing?', 'The level of formality chosen to suit the genre and audience.', 23),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is the purpose of drafting?', 'Improving writing through revision and editing.', 24),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'How should the commentary refer to the style model?', 'It should show how the writer adapted conventions from the style model.', 25),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is lexical choice?', 'The selection of particular words for effect.', 26),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is syntactical choice?', 'The arrangement of sentences for effect, e.g. short sentences for tension.', 27),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is graphological choice?', 'The use of layout, fonts and images to create meaning.', 28),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'Why is linguistic terminology important in the commentary?', 'It shows precise understanding of language choices.', 29),
  ('English Language', 'AQA', 'alevel', '3.2', 'Original Writing & Commentary (NEA)', 'What is the relationship between purpose and form?', 'The form (genre and structure) should suit the text''s purpose.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'English Language' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

