  ('English Language', 'Edexcel', 'alevel', '1.1', 'Individual and Social Variation', 'What is Standard English?', 'The prestige variety of English used in formal writing and education, not tied to a region.', 3),
  ('English Language', 'Edexcel', 'alevel', '1.1', 'Individual and Social Variation', 'What is Received Pronunciation (RP)?', 'A prestige accent traditionally associated with the upper and middle classes.', 4),
