  ('English Language', 'Edexcel', 'alevel', '1.1', 'Individual and Social Variation', 'What is covert prestige?', 'Status gained by using non-standard language within a group.', 7),
  ('English Language', 'Edexcel', 'alevel', '1.1', 'Individual and Social Variation', 'What is overt prestige?', 'Status gained by using standard, socially recognised language.', 8),
