  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is language change?', 'The ways a language develops over time in lexis, grammar, pronunciation and meaning.', 1),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is Old English?', 'English spoken from about 450 to 1100, influenced by Germanic languages.', 2),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is Middle English?', 'English spoken from about 1100 to 1500, heavily influenced by French after the Norman Conquest.', 3),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is Early Modern English?', 'English from about 1500 to 1700, the time of Shakespeare and the printing press.', 4),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is the Great Vowel Shift?', 'A major change in the pronunciation of long vowels in English, from about 1400 to 1700.', 5),
