  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is Aitchison''s damp spoon syndrome?', 'The view that language change is due to laziness, which Aitchison rejects.', 23),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is Aitchison''s crumbling castle view?', 'The view that language was once perfect and is decaying, which Aitchison rejects.', 24),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is Aitchison''s infectious disease view?', 'The view that bad language habits spread like a disease, which Aitchison rejects.', 25),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is the S-curve model of change?', 'Change starts slowly, spreads rapidly, then slows as it reaches most speakers.', 26),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is the wave model of change?', 'Change spreads outwards from a central point, like ripples.', 27),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is the functional theory of change?', 'Language changes to meet the needs of its users, e.g. new technology.', 28),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is random fluctuation theory?', 'Language changes randomly, without a specific cause.', 29),
  ('English Language', 'Edexcel', 'alevel', '1.2', 'Historical Language Change', 'What is the effect of technology on language change?', 'New words (e.g. "selfie"), new forms of communication, and faster spread of change.', 30),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is ethnolect?', 'A variety of language associated with an ethnic group.', 1),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is World English?', 'The varieties of English used around the world.', 2),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Kachru''s concentric circles model?', 'Inner circle (native speakers, e.g. UK), outer circle (second language, e.g. India), expanding circle (foreign language, e.g. China).', 3),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is a lingua franca?', 'A language used for communication between speakers of different languages.', 4),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'Why is English a global lingua franca?', 'Colonialism, US economic and cultural power, and its use in science, business and the internet.', 5),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is a pidgin?', 'A simplified language that develops for communication between groups without a common language.', 6),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is a creole?', 'A pidgin that has become the first language of a community, with a full grammar.', 7),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Singlish?', 'Singapore English, with influences from Malay, Chinese and Tamil.', 8),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Indian English?', 'The variety of English spoken in India, with distinctive vocabulary and grammar.', 9),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is linguistic imperialism?', 'The dominance of one language over others, often linked to colonial or economic power (Phillipson).', 10),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is language death?', 'When a language no longer has any native speakers.', 11),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Jenkins''s Lingua Franca Core?', 'Key pronunciation features needed for international intelligibility in English.', 12),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Crystal''s view of global English?', 'English will continue to spread and diversify into many varieties.', 13),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is McArthur''s circle of World English?', 'A model with World Standard English at the centre, surrounded by regional varieties.', 14),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Multicultural London English?', 'A multiethnolect spoken by young Londoners from diverse backgrounds.', 15),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is a multiethnolect?', 'A variety that develops from contact between many ethnic groups.', 16),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is crossing?', 'Using a language variety associated with a different ethnic group (Rampton).', 17),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What did Rampton''s study show?', 'Young people used features of other ethnic groups'' languages to express identity.', 18),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Kerswill''s research on MLE?', 'He found MLE was spoken by young people of all ethnicities in London.', 19),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is identity in language?', 'How language expresses who we are, including ethnicity, class and region.', 20),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What are attitudes to ethnolects?', 'Some view them negatively as "incorrect"; others see them as valid expressions of identity.', 21),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is language planning?', 'Deliberate efforts to influence language use, e.g. making a language official.', 22),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Global English''s impact on other languages?', 'Loanwords enter other languages, and some fear loss of linguistic diversity.', 23),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is code-mixing?', 'Mixing words from two languages within a sentence.', 24),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Hinglish?', 'A mix of Hindi and English used in India.', 25),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Nigerian English?', 'A variety of English spoken in Nigeria, with distinctive vocabulary and grammar.', 26),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is linguistic diversity?', 'The variety of languages and dialects in the world.', 27),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'Why do some people resist Global English?', 'To protect national languages and cultural identity, e.g. French language laws.', 28),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is the role of the internet in Global English?', 'It spreads English worldwide and creates new varieties and vocabulary.', 29),
  ('English Language', 'Edexcel', 'alevel', '1.3', 'Global and Regional Variation', 'What is Englishisation?', 'The influence of English on other languages and cultures.', 30),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What are the stages of children''s spoken language development?', 'Pre-verbal (cooing, babbling), holophrastic, two-word, telegraphic, and post-telegraphic.', 1),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is cooing?', 'Early vowel-like sounds made by babies from about 6–8 weeks.', 2),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is babbling?', 'Repeated consonant–vowel combinations, e.g. "bababa", from about 6 months.', 3),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is the holophrastic stage?', 'Around 12–18 months, when children use single words to express whole ideas.', 4),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is the two-word stage?', 'Around 18–24 months, when children combine two words, e.g. "daddy go".', 5),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is the telegraphic stage?', 'Around 24–36 months, when children use short phrases with mainly content words, omitting function words.', 6),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is overextension?', 'Using a word too broadly, e.g. calling all animals "dog".', 7),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is underextension?', 'Using a word too narrowly, e.g. using "cat" only for the family cat.', 8),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is a virtuous error?', 'A mistake that shows a child is applying a grammar rule logically, e.g. "I goed".', 9),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is overgeneralisation?', 'Applying a rule too widely, e.g. adding "-s" to make "mouses".', 10),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Skinner''s theory?', 'Behaviourism: children learn language through imitation and reinforcement.', 11),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Chomsky''s theory?', 'Nativism: children have an innate Language Acquisition Device (LAD) that enables them to learn language.', 12),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Piaget''s theory?', 'Cognitive theory: language develops as children''s thinking develops.', 13),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Bruner''s theory?', 'Interactionism: children learn through interaction with caregivers, supported by a Language Acquisition Support System (LASS).', 14),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is child-directed speech (CDS)?', 'The way adults speak to young children: simplified vocabulary, repetition, higher pitch and exaggerated intonation.', 15),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is scaffolding?', 'Support given by adults to help children achieve what they can''t yet do alone.', 16),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is the critical period hypothesis?', 'The idea that there is a window in childhood when language must be acquired.', 17),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What does the case of Genie suggest?', 'Genie was deprived of language until 13 and never fully acquired grammar, supporting the critical period hypothesis.', 18),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s instrumental function?', 'Language used to get things, e.g. "I want".', 19),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s regulatory function?', 'Language used to control others'' behaviour.', 20),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s interactional function?', 'Language used to form relationships.', 21),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s personal function?', 'Language used to express feelings and identity.', 22),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s heuristic function?', 'Language used to learn about the environment, e.g. asking questions.', 23),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s imaginative function?', 'Language used for play and storytelling.', 24),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Halliday''s representational function?', 'Language used to convey information.', 25),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is phonological development?', 'How children learn to produce the sounds of their language.', 26),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is deletion in phonological development?', 'Omitting sounds, e.g. "nana" for "banana".', 27),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is substitution in phonological development?', 'Replacing one sound with an easier one, e.g. "wabbit" for "rabbit".', 28),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is consonant cluster reduction?', 'Simplifying clusters, e.g. "pider" for "spider".', 29),
  ('English Language', 'Edexcel', 'alevel', '2.1', 'Children''s Spoken Language Development', 'What is Brown''s order of morpheme acquisition?', 'The order in which children acquire grammatical morphemes, e.g. "-ing" first, then plural "-s", then possessive "''s".', 30),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What are the stages of children''s written development?', 'Kroll''s stages: preparation, consolidation, differentiation and integration.', 1),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is Kroll''s preparation stage?', 'Up to about 6 years: learning motor skills and basic spelling.', 2),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is Kroll''s consolidation stage?', 'About 7–8 years: writing like speaking, with simple sentences and "and" as the main conjunction.', 3),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is Kroll''s differentiation stage?', 'About 9–10 years: understanding differences between speech and writing, and using genre conventions.', 4),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is Kroll''s integration stage?', 'Mid-teens onwards: developing a personal voice and control of style.', 5),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What are Barclay''s stages of writing?', 'Scribbling, mock handwriting, mock letters, conventional letters, invented spelling, appropriate spelling, and correct spelling.', 6),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is Rothery''s categorisation of children''s writing?', 'Observation/comment, recount, report and narrative.', 7),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is phonetic spelling?', 'Spelling words as they sound, e.g. "sed" for "said".', 8),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is insertion in spelling?', 'Adding extra letters, e.g. "whent" for "went".', 9),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is omission in spelling?', 'Leaving out letters, e.g. "wich" for "which".', 10),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is transposition in spelling?', 'Reversing letters, e.g. "form" for "from".', 11),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is overgeneralisation in spelling?', 'Applying a spelling rule incorrectly, e.g. "happyly".', 12),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is a homophone error?', 'Using the wrong word with the same sound, e.g. "there" for "their".', 13),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is synthetic phonics?', 'Teaching reading by blending individual letter sounds to form words.', 14),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is the whole-word (look and say) approach?', 'Teaching children to recognise whole words by sight.', 15),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is emergent literacy?', 'The early reading and writing skills children develop before formal teaching.', 16),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What does Clay''s research show about writing?', 'Children understand concepts such as directionality and spacing gradually.', 17),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is the role of reading in writing development?', 'Exposure to texts helps children learn vocabulary, spelling and genre conventions.', 18),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What are features of early narrative writing?', 'Simple chronology, first-person perspective, repetition of "and then", and limited description.', 19),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'How do children''s texts show developing cohesion?', 'Increasing use of pronouns, connectives and varied sentence openings.', 20),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is the role of the teacher''s feedback?', 'It helps children correct errors and develop their writing.', 21),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is a genre convention?', 'An expected feature of a type of text, e.g. "Once upon a time" in stories.', 22),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What does increasing sentence complexity show?', 'Growing grammatical knowledge, such as subordination and embedded clauses.', 23),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is the difference between spoken and written language for children?', 'Early writing mirrors speech; children gradually learn more formal written structures.', 24),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'How does technology affect children''s literacy?', 'Texting and digital media may develop phonological awareness and creativity; there are debates over its effect on spelling.', 25),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What did Plester''s research find about texting?', 'Children who used more textisms often had better phonological awareness and literacy.', 26),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is handwriting development?', 'From scribbles to letter formation, then joined and fluent writing.', 27),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is metalinguistic awareness?', 'The ability to think and talk about language itself.', 28),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is Kress''s theory on children''s writing?', 'Children''s writing develops as they learn the differences between speech and writing, and use conventions.', 29),
  ('English Language', 'Edexcel', 'alevel', '2.2', 'Children''s Written Language Development', 'What is punctuation development?', 'Children learn full stops and capitals first, then commas, speech marks and more complex punctuation.', 30),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the spread of English often divided into?', 'The first diaspora (migration of native speakers to North America and Australasia) and the second diaspora (colonial spread to Asia and Africa).', 1),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the first diaspora of English?', 'The migration of English speakers to countries such as the USA, Canada, Australia and New Zealand.', 2),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the second diaspora of English?', 'The spread of English through colonisation to places such as India, Nigeria and Singapore, where it became a second language.', 3),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Schneider''s Dynamic Model?', 'A model of how postcolonial Englishes develop through five phases: foundation, exonormative stabilisation, nativisation, endonormative stabilisation and differentiation.', 4),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is nativisation?', 'When a variety of English develops its own local features and identity.', 5),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is endonormative stabilisation?', 'When a local variety of English is accepted as a standard in its own right.', 6),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is exonormative?', 'Looking to an external norm (e.g. British English) as the standard.', 7),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is a New English?', 'A variety of English that developed in a former colony, e.g. Indian English or Singapore English.', 8),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What are common grammatical features of New Englishes?', 'Invariant tag questions ("isn''t it?"), use of progressive with stative verbs ("I am knowing"), and pluralising uncountable nouns ("furnitures").', 9),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is an invariant tag question?', 'A tag that doesn''t change with the verb, e.g. "You''re coming, isn''t it?"', 10),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Singlish''s use of discourse particles?', 'Particles like "lah", "leh" and "lor" express attitude and emphasis.', 11),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Nigerian Pidgin?', 'An English-based pidgin/creole widely spoken as a lingua franca in Nigeria.', 12),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Jamaican Creole (Patois)?', 'An English-based creole spoken in Jamaica, with West African influences.', 13),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is decreolisation?', 'When a creole becomes more like the standard language through contact.', 14),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is a post-creole continuum?', 'A range of varieties from the creole (basilect) to the standard (acrolect).', 15),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the acrolect?', 'The variety closest to the standard language.', 16),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the basilect?', 'The variety furthest from the standard language.', 17),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the mesolect?', 'An intermediate variety between the acrolect and basilect.', 18),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is English as a Lingua Franca (ELF)?', 'English used as a common language between speakers whose first languages differ.', 19),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Jenkins''s view of ELF?', 'ELF has its own norms, and intelligibility matters more than native-speaker correctness.', 20),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the Expanding Circle?', 'Countries where English is learned as a foreign language, e.g. China, Japan and Brazil.', 21),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the Outer Circle?', 'Countries where English has an official or institutional role as a second language, e.g. India and Nigeria.', 22),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Global English''s relationship with the internet?', 'English dominates online content, spreading its influence and creating new varieties.', 23),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the attitude of "standard ideology" to World Englishes?', 'It sees British or American English as correct and other varieties as deficient.', 24),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the attitude of linguistic pluralism?', 'All varieties of English are valid and rule-governed.', 25),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is language shift?', 'When a community gradually replaces its language with another, e.g. English.', 26),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the role of English in education globally?', 'English is often the medium of instruction in higher education, giving access to opportunities but disadvantaging non-speakers.', 27),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is Chinglish?', 'A mix of Chinese and English, often used informally.', 28),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What is the impact of American English globally?', 'Through media and business, American vocabulary and spelling spread worldwide.', 29),
  ('English Language', 'Edexcel', 'alevel', '3.1', 'Global English (Paper 3 pathway)', 'What are borrowings from other languages into English?', 'E.g. "bungalow" and "shampoo" (Hindi), "tsunami" (Japanese), "safari" (Swahili).', 30),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the deficit model of gender and language?', 'Lakoff''s view that women''s language is weaker and less assertive than men''s.', 1),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What features did Lakoff identify in women''s speech?', 'Hedges, tag questions, empty adjectives, super-polite forms and intensifiers.', 2),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the dominance model?', 'Zimmerman and West''s view that men dominate conversation, e.g. through interruptions.', 3),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What did Zimmerman and West find?', 'In mixed-sex conversations, men made most of the interruptions.', 4),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the difference model?', 'Tannen''s view that men and women have different conversational styles.', 5),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What are Tannen''s six contrasts?', 'Status/support, independence/intimacy, advice/understanding, information/feelings, orders/proposals, conflict/compromise.', 6),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the diversity model?', 'The view that gender is one of many factors affecting language, and variation within genders is greater than between them.', 7),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What did Cameron argue?', 'Differences in language are due to context and power rather than gender; she challenged the "myth of Mars and Venus".', 8),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is Butler''s theory of gender performativity?', 'Gender is something we perform through repeated behaviour, including language.', 9),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is a hedge?', 'A word or phrase that softens a statement, e.g. "sort of", "maybe".', 10),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is a tag question?', 'A question added to a statement, e.g. "It''s cold, isn''t it?"', 11),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What did Holmes find about tag questions?', 'Women often used tag questions to facilitate conversation, not due to uncertainty.', 12),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What did Fishman find?', 'Women did more "conversational shitwork", asking questions to keep conversations going.', 13),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is sexist language?', 'Language that discriminates or stereotypes based on gender, e.g. "fireman".', 14),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is semantic derogation?', 'When words associated with women develop negative meanings over time, e.g. "mistress".', 15),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the generic "he"?', 'Using "he" to refer to people in general, now seen as exclusive.', 16),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is marked language?', 'Adding a gender marker to show difference from the norm, e.g. "female doctor".', 17),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What are gender-neutral terms?', 'Words that don''t specify gender, e.g. "firefighter" or "chair".', 18),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is singular "they"?', 'Using "they" to refer to one person of unknown or non-binary gender.', 19),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'How is gender represented in the media?', 'Through stereotypical language, e.g. focusing on women''s appearance.', 20),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is lexical asymmetry?', 'Unequal pairs of words, e.g. "bachelor" (positive) versus "spinster" (negative).', 21),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What did Coates find about all-female talk?', 'Women used cooperative strategies such as minimal responses and overlapping speech.', 22),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is a minimal response?', 'Short responses like "mm" or "yeah" to show listening.', 23),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What did Beattie find about interruptions?', 'Women interrupted as much as men, challenging the dominance model.', 24),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is Jespersen''s view of women''s language?', 'An early, stereotyped view that women''s language was inferior and less complex.', 25),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'How do gender and language interact in the workplace?', 'Power and role often affect language more than gender.', 26),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the "gendered" language in children''s toys?', 'Boys'' toys use action and power words; girls'' toys use appearance and caring words.', 27),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is political correctness in language?', 'Avoiding language that may exclude or offend groups.', 28),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is the role of social media in gendered language?', 'It allows new identities and challenges norms, but can also reinforce stereotypes.', 29),
  ('English Language', 'Edexcel', 'alevel', '3.2', 'Language and Gender Identity (Paper 3 pathway)', 'What is linguistic reform?', 'Changing language to make it less sexist, e.g. "Ms" instead of "Miss" or "Mrs".', 30),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is the language of journalism?', 'The distinctive language used in news reporting, features and opinion pieces.', 1),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What are the features of a headline?', 'Short, eye-catching, often omitting function words, using puns, alliteration and present tense.', 2),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is headlinese?', 'The compressed style of headlines, e.g. "PM slams critics".', 3),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is a standfirst?', 'A short summary under the headline that introduces the story.', 4),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is the inverted pyramid structure?', 'News stories begin with the most important information, followed by details in decreasing importance.', 5),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What are the 5 Ws of news writing?', 'Who, what, when, where and why (and often how).', 6),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is a tabloid newspaper?', 'A newspaper with a popular, sensationalist style, e.g. The Sun.', 7),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is a broadsheet newspaper?', 'A traditionally serious newspaper with in-depth reporting, e.g. The Guardian or The Times.', 8),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What are typical language features of tabloids?', 'Informal register, puns, short sentences, emotive language and colloquialisms.', 9),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What are typical language features of broadsheets?', 'Formal register, complex sentences, specialist vocabulary and a more neutral tone.', 10),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is news values?', 'Criteria that make events newsworthy, e.g. negativity, proximity, celebrity and unexpectedness (Galtung and Ruge).', 11),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is bias in journalism?', 'Presenting news in a way that favours one side or viewpoint.', 12),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is framing?', 'Presenting a story in a way that shapes how the audience interprets it.', 13),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is agenda-setting?', 'The media''s power to influence which issues the public thinks are important.', 14),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is gatekeeping?', 'The process of selecting which stories are published and which are left out.', 15),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is sensationalism?', 'Presenting stories in an exaggerated way to attract attention.', 16),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is clickbait?', 'Online headlines designed to make readers click, often by being misleading or intriguing.', 17),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is citizen journalism?', 'News reporting by members of the public, often through social media.', 18),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is the role of quotations in news reports?', 'They provide evidence, voices and authority, and can be selected to support a viewpoint.', 19),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is reported speech?', 'Reporting what someone said without their exact words, e.g. "She said she was tired".', 20),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is direct speech?', 'The exact words someone said, in quotation marks.', 21),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'How can reporting verbs show bias?', 'Choices like "claimed", "admitted" or "insisted" suggest attitudes towards the speaker.', 22),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is an opinion piece?', 'An article expressing the writer''s views, using persuasive language.', 23),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is an editorial?', 'An article expressing the newspaper''s official opinion.', 24),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is the representation of groups in news?', 'How people are portrayed, e.g. through labels, stereotypes and agency.', 25),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is transitivity in news reports?', 'How sentences show who does what to whom, which can affect blame and responsibility.', 26),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is nominalisation''s effect in news?', 'It can hide who performed an action, e.g. "the killing" rather than "police killed".', 27),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is the effect of online news on language?', 'Shorter articles, hyperlinks, multimedia, interactivity and faster updates.', 28),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is fake news?', 'False information presented as news, often spread online.', 29),
  ('English Language', 'Edexcel', 'alevel', '3.3', 'Language of Journalism (Paper 3 pathway)', 'What is the role of images in news?', 'They attract attention and shape how readers interpret stories.', 30),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is power in language?', 'The ability of language to influence, control or dominate others.', 1),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is instrumental power?', 'Power exercised through authority and rules, e.g. laws and official instructions.', 2),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is influential power?', 'Power exercised through persuasion, e.g. advertising and political speeches.', 3),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'Who distinguished instrumental and influential power?', 'Wareing.', 4),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is political power in language?', 'Power held by those in government and expressed through speeches, laws and policy documents.', 5),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is personal power?', 'Power based on someone''s role or status, e.g. a teacher or boss.', 6),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is social group power?', 'Power based on belonging to a dominant social group, e.g. class, gender or ethnicity.', 7),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is Fairclough''s view of power?', 'Power is exercised through discourse, often hidden (hidden power) in the media and institutions.', 8),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is hidden power?', 'Power that operates subtly through language, e.g. in the media, without obvious coercion.', 9),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is power behind discourse?', 'The way social structures shape what can be said and who can say it.', 10),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is power in discourse?', 'The way powerful participants control conversations, e.g. by interrupting or setting topics.', 11),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is synthetic personalisation?', 'Treating a mass audience as individuals to create false intimacy, e.g. "you" in adverts (Fairclough).', 12),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is a sequence of turn-taking in powerful talk?', 'Powerful speakers often control turns, e.g. in interviews or classrooms.', 13),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is the IRF model?', 'Initiation, response, feedback: a pattern in classroom talk controlled by teachers (Sinclair and Coulthard).', 14),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is Brown and Levinson''s politeness theory?', 'People use politeness strategies to protect face, based on power, distance and imposition.', 15),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is positive politeness?', 'Strategies that show friendliness and solidarity, e.g. compliments.', 16),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is negative politeness?', 'Strategies that avoid imposing, e.g. apologies and indirect requests.', 17),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is a bald on-record strategy?', 'A direct statement with no politeness, used when power is high or urgency requires.', 18),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is an off-record strategy?', 'An indirect hint, e.g. "It''s cold in here" instead of "Close the window".', 19),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is Grice''s cooperative principle?', 'Speakers assume cooperation and follow maxims of quantity, quality, relation and manner.', 20),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'How is power shown in political speeches?', 'Through rhetoric, inclusive pronouns ("we"), repetition, tricolon and emotive language.', 21),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is inclusive "we"?', 'Using "we" to include the audience, creating unity.', 22),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is exclusive "we"?', 'Using "we" to refer to a group that excludes the audience.', 23),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'How is power shown in legal language?', 'Formal register, specialised vocabulary, complex sentences and precise definitions.', 24),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'How is power shown in advertising?', 'Persuasive techniques: imperatives, superlatives, emotive language and claims.', 25),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is Lakoff''s view of power and politeness?', 'Rules of politeness include "don''t impose", "give options" and "make the listener feel good".', 26),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is an interrogation''s power dynamic?', 'Questioners control the discourse; respondents are expected to answer.', 27),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is power in workplace talk?', 'Seen in who speaks first, who interrupts, and how requests are made.', 28),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What is gender and power in language?', 'Research suggests power often explains differences attributed to gender (e.g. O''Barr and Atkins).', 29),
  ('English Language', 'Edexcel', 'alevel', '3.4', 'Language and Power (Paper 3 pathway)', 'What did O''Barr and Atkins find?', '"Women''s language" features in court were linked to low power, not gender ("powerless language").', 30),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is regional variation?', 'Differences in accent and dialect between different places.', 1),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What are features of Geordie English?', 'E.g. "why aye" (yes), "hinny", and distinctive vowels such as "toon" for "town".', 2),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What are features of Scouse?', 'E.g. a distinctive fricative /k/ and /t/, and words like "scran" (food).', 3),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What are features of Brummie English?', 'Distinctive intonation and vowel sounds, e.g. "I" pronounced like "oy".', 4),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What are features of Cockney?', 'H-dropping, glottal stops, th-fronting ("fink"), and rhyming slang.', 5),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is rhyming slang?', 'Replacing a word with a phrase that rhymes with it, e.g. "apples and pears" (stairs).', 6),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is th-fronting?', 'Pronouncing "th" as /f/ or /v/, e.g. "fink" and "bruvver".', 7),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is the north–south divide in English accents?', 'E.g. short /a/ in "bath" in the north, long /ɑː/ in the south.', 8),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is the FOOT–STRUT split?', 'In the south, "foot" and "strut" have different vowels; in the north they have the same.', 9),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is rhoticity?', 'Pronouncing the /r/ after vowels, e.g. in "car"; found in the south-west, Scotland and Ireland.', 10),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is a non-rhotic accent?', 'An accent that doesn''t pronounce /r/ after vowels, e.g. RP.', 11),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is dialect vocabulary?', 'Regional words, e.g. "bairn" (child, north-east and Scotland), "ginnel" (alley, Yorkshire).', 12),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is a regional grammatical feature?', 'E.g. "I were" in Yorkshire or "youse" for plural "you" in Liverpool.', 13),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is the Survey of English Dialects?', 'A major survey from the 1950s recording traditional dialect features across England.', 14),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is the BBC Voices project?', 'A 2005 survey of attitudes to and use of regional language across the UK.', 15),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What are attitudes to regional accents?', 'Some accents are seen as more prestigious or trustworthy, others face prejudice.', 16),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What did Giles''s matched guise experiment show?', 'Listeners judged speakers differently based on accent alone.', 17),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is accent prejudice?', 'Negative judgements about people based on their accent, e.g. in job interviews.', 18),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is dialect levelling?', 'The reduction of regional differences as people move and mix.', 19),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is the role of mobility in dialect change?', 'People moving between regions spreads features and levels dialects.', 20),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is urban dialect?', 'Dialects spoken in cities, often changing quickly, e.g. MLE.', 21),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is rural dialect?', 'Traditional dialects in rural areas, often declining.', 22),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is the impact of the media on regional variation?', 'Exposure to standard forms may reduce variation, but regional voices are increasingly heard.', 23),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is regional identity?', 'The sense of belonging to a place, often expressed through accent and dialect.', 24),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is a heteroglossia?', 'The coexistence of different varieties within one language or text.', 25),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What did Trudgill predict about English dialects?', 'He predicted continued levelling and the spread of features such as th-fronting.', 26),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is Scottish English?', 'Standard English spoken with Scottish pronunciation and some distinctive vocabulary.', 27),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is Scots?', 'A Germanic language variety closely related to English, spoken in Scotland.', 28),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is Welsh English?', 'English spoken in Wales, influenced by the Welsh language, e.g. distinctive intonation.', 29),
  ('English Language', 'Edexcel', 'alevel', '3.5', 'Language and Regional Variation (Paper 3 pathway)', 'What is Hiberno-English?', 'English spoken in Ireland, influenced by Irish, e.g. "I''m after eating".', 30),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the Edexcel coursework (NEA) called?', 'Crafting Language: writing original pieces and a reflective commentary on the writing process and choices.', 1),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What does the Edexcel NEA involve?', 'Researching a genre, producing two pieces of original writing for different audiences or purposes, and writing a commentary.', 2),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is genre research?', 'Studying examples of a genre to understand its conventions before writing.', 3),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a style model?', 'An existing text used as a model for writing in a genre.', 4),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is audience in original writing?', 'The intended readers, which affects register, vocabulary and structure.', 5),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is purpose in original writing?', 'The aim of the text, e.g. to inform, persuade or entertain.', 6),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'Why should both NEA pieces be clearly differentiated?', 'Showing contrasting audiences or purposes lets the writer demonstrate control of different registers, forms and conventions.', 7),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a commentary?', 'An analysis explaining the writer''s language choices and their intended effects.', 8),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What should the commentary analyse?', 'Choices of lexis, grammar, structure, graphology and pragmatics, linked to audience and purpose.', 9),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is adaptation of style?', 'Changing a text''s style to suit a different audience or purpose.', 10),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is voice in writing?', 'The distinctive personality or style of a writer or narrator.', 11),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is tone?', 'The writer''s attitude, e.g. humorous, serious or sarcastic.', 12),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a persuasive text?', 'A text designed to convince the reader, e.g. a speech or opinion column.', 13),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is an informative text?', 'A text designed to provide information clearly and accurately.', 14),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is an entertaining text?', 'A text designed to engage and amuse, e.g. a short story or blog.', 15),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a monologue?', 'A text spoken by one person, often revealing thoughts and character.', 16),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a script?', 'A written text for performance, with dialogue and stage directions.', 17),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a podcast script?', 'A spoken text written to sound natural, using discourse markers and direct address.', 18),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a feature article?', 'A longer journalistic piece exploring a topic in depth, often with a personal angle.', 19),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is a blog?', 'An online text with a personal voice, informal register and interactive features.', 20),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'How is spoken language represented in writing?', 'Through features such as contractions, discourse markers, fillers and informal lexis.', 21),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the role of drafting?', 'Improving writing through feedback and revision.', 22),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is textual cohesion?', 'Linking ideas in a text through connectives, pronouns and repetition.', 23),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the effect of short sentences?', 'They create emphasis, tension or pace.', 24),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the effect of complex sentences?', 'They add detail and show relationships between ideas.', 25),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the effect of rhetorical questions?', 'They engage the reader and encourage them to think.', 26),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the effect of direct address?', 'It creates a personal connection with the reader.', 27),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is the effect of imagery?', 'It creates vivid pictures in the reader''s mind.', 28),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'What is bibliography in the NEA?', 'A list of style models and sources used.', 29),
  ('English Language', 'Edexcel', 'alevel', '4.1', 'Crafting Language (NEA)', 'Why must the commentary use linguistic terminology?', 'It demonstrates precise understanding of language choices and their effects.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'English Language' AND exam_board = 'Edexcel' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
