  ('Geography', 'Eduqas', 'alevel', '2.5', '21st Century Challenges', 'What is global governance?', 'Cooperation between states, international organisations and NGOs to address global issues.', 9),
  ('Geography', 'Eduqas', 'alevel', '2.5', '21st Century Challenges', 'What is the role of the IPCC?', 'The Intergovernmental Panel on Climate Change assesses scientific evidence on climate change and informs policy.', 10),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is a volcanic hazard?', 'A threat from volcanic activity, such as lava flows, ash fall, pyroclastic flows, lahars and gases.', 1),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is a tephra?', 'Fragments of rock and ash ejected into the air during an eruption.', 2),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is a primary effect of an earthquake?', 'An effect caused directly by ground shaking, e.g. buildings collapsing.', 3),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is a secondary effect of an earthquake?', 'An effect caused indirectly, e.g. fires, tsunamis, landslides and disease.', 4),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is the Modified Mercalli scale?', 'A scale measuring earthquake intensity by observed effects, from I to XII.', 5),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is a tsunami warning system?', 'A network of seismometers and ocean buoys that detects tsunamis and issues warnings.', 6),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is the role of education in hazard preparedness?', 'It teaches people what to do in a hazard event, e.g. earthquake drills, reducing casualties.', 7),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is the difference between a hazard and a disaster?', 'A hazard is a potential threat; a disaster occurs when a hazard seriously disrupts a community.', 8),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is the role of social factors in vulnerability?', 'Poverty, age, gender, education and poor housing increase vulnerability to hazards.', 9),
  ('Geography', 'Eduqas', 'alevel', '3.1', 'Tectonic Hazards', 'What is resilience?', 'The ability of a community to withstand, recover from and adapt to hazards.', 10),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is a food chain?', 'A sequence showing how energy is transferred from producers to consumers through feeding.', 1),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is a trophic level?', 'A position in a food chain: producer, primary consumer, secondary consumer and so on.', 2),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is net primary productivity?', 'The rate at which plants store energy as biomass, after respiration losses.', 3),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is the nutrient cycle?', 'The movement of nutrients between biomass, litter and soil.', 4),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is a climatic climax community?', 'The final stable community in succession, determined by the climate.', 5),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is an arrested succession?', 'When succession is prevented from reaching the climax by a factor such as grazing or burning.', 6),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is the role of fire in savanna ecosystems?', 'Fire maintains grassland by preventing tree growth and recycling nutrients.', 7),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is desertification?', 'Land degradation in dry areas caused by climate change and human activities such as overgrazing.', 8),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is the biodiversity hotspot concept?', 'Areas with very high numbers of endemic species that are under threat, prioritised for conservation.', 9),
  ('Geography', 'Eduqas', 'alevel', '3.2', 'Ecosystems', 'What is ecotourism?', 'Responsible tourism that conserves the environment and benefits local communities.', 10)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'Eduqas' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

