  ('Geography', 'Eduqas', 'gcse', '2.3', 'Global Development', 'What is a multinational company?', 'A company that operates in more than one country.', 20),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Global Development', 'What are the advantages of TNCs to poorer countries?', 'Jobs, investment, skills and infrastructure.', 21),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Global Development', 'What are the disadvantages of TNCs to poorer countries?', 'Low wages, poor conditions, profits going abroad, and environmental damage.', 22),
  ('Geography', 'Eduqas', 'gcse', '2.3', 'Global Development', 'What is the Demographic Transition Model?', 'A model showing how birth and death rates change as a country develops.', 23),
