  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is greywater recycling?', 'Reusing water from sinks, showers and washing machines for flushing toilets or watering gardens.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is rainwater harvesting?', 'Collecting and storing rainwater for use.', 17),
