  ('Geography', 'OCR', 'alevel', '2.3', 'Global Migration', 'What are the benefits of migration to source countries?', 'Remittances, reduced unemployment, and skills brought back by returning migrants.', 7),
  ('Geography', 'OCR', 'alevel', '2.3', 'Global Migration', 'What are the costs of migration to source countries?', 'Brain drain, loss of young workers, and an ageing population left behind.', 8),
