  ('Geography', 'OCR', 'alevel', '2.3', 'Global Migration', 'What is integration?', 'The process by which migrants become part of the host society while maintaining their own culture.', 10),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is the Universal Declaration of Human Rights?', 'A 1948 UN document setting out basic rights and freedoms for all people.', 1),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is freedom of speech?', 'The right to express opinions without censorship or restraint.', 2),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is the role of NGOs in protecting human rights?', 'They monitor abuses, campaign for change, and support victims, e.g. Amnesty International.', 3),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is the relationship between development and human rights?', 'Development can improve rights through education and healthcare, but rights violations can occur in the pursuit of growth.', 4),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is a child''s right under the UN Convention on the Rights of the Child?', 'Rights including education, protection from exploitation, healthcare and play.', 5),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is the role of the International Criminal Court?', 'It prosecutes individuals for genocide, war crimes and crimes against humanity.', 6),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What are women''s rights issues globally?', 'Access to education, political representation, equal pay, and protection from violence and forced marriage.', 7),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is the role of the UN Human Rights Council?', 'It promotes and protects human rights worldwide and reviews the human rights records of member states.', 8),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is sovereignty versus intervention?', 'The tension between a state''s right to govern itself and the international community''s responsibility to protect human rights.', 9),
  ('Geography', 'OCR', 'alevel', '2.4', 'Human Rights', 'What is development aid''s role in human rights?', 'It can improve access to education, health and clean water, supporting economic and social rights.', 10),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is geopolitics?', 'The study of how geography, including location and resources, influences political power and international relations.', 1),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is a border?', 'A line separating two political or geographical areas, such as countries.', 2),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is a natural border?', 'A border following a physical feature, such as a river or mountain range.', 3),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is an artificial border?', 'A border drawn along lines of latitude or longitude, often imposed by colonial powers.', 4),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is a stateless nation?', 'A national group without its own state, e.g. the Kurds.', 5),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is territorial integrity?', 'The principle that a state''s borders should not be changed by force.', 6),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is irredentism?', 'A claim to territory in another state on the basis of shared ethnicity or history.', 7),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is the role of the UN in border disputes?', 'It mediates, sends peacekeepers and upholds international law on territorial integrity.', 8),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is a failed state?', 'A state whose government cannot provide basic services, security or control over its territory.', 9),
  ('Geography', 'OCR', 'alevel', '2.5', 'Power & Borders', 'What is the role of power in shaping borders?', 'Powerful states can influence or redraw borders through military force, economic pressure and diplomacy.', 10)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'OCR' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

