  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a Public Bill Committee?', 'A committee that examines bills line by line after second reading.', 5),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a select committee?', 'A committee that scrutinises government departments or policy areas.', 6),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is Prime Minister''s Questions?', 'A weekly session where MPs question the Prime Minister.', 7),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the role of the opposition?', 'To scrutinise and criticise the government and present itself as an alternative government.', 8),
