WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is democracy?', 'A system of government in which power rests with the people, who exercise it directly or through elected representatives.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is direct democracy?', 'Citizens make decisions themselves, e.g. through referendums, rather than electing representatives.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is representative democracy?', 'Citizens elect representatives to make decisions on their behalf, and hold them accountable at elections.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'Give two advantages of direct democracy.', 'It gives decisions strong legitimacy and increases political participation and education.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'Give two disadvantages of direct democracy.', 'Complex issues are oversimplified, and it risks the tyranny of the majority and low turnout.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is pluralist democracy?', 'A democracy where power is dispersed among many competing groups, such as parties and pressure groups.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is the franchise?', 'The right to vote in elections.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'When did women gain equal voting rights with men in the UK?', '1928 (Representation of the People (Equal Franchise) Act); some women over 30 had gained the vote in 1918.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'When was the voting age lowered to 18 in the UK?', '1969, by the Representation of the People Act.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What are the arguments for lowering the voting age to 16?', '16-year-olds pay taxes, can work and marry; it may increase engagement; and 16-year-olds already vote in Scottish and Welsh elections.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What are the arguments against votes at 16?', 'Lack of maturity and experience, low turnout among young voters, and inconsistency with other age limits.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is a pressure group?', 'An organisation that seeks to influence government policy without seeking election to office.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is an insider group?', 'A pressure group with close links to and regular access to government, e.g. the BMA.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is an outsider group?', 'A pressure group without access to government, which uses public campaigns and direct action, e.g. Extinction Rebellion.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is a think tank?', 'An organisation that researches and develops policy ideas to influence government, e.g. the Institute for Fiscal Studies.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is a lobbyist?', 'A professional paid to influence politicians and policy on behalf of clients.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is e-democracy?', 'The use of digital technology in democratic processes, e.g. online petitions and social media campaigns.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What happens to a UK Parliament e-petition with 100,000 signatures?', 'It is considered for debate in Parliament by the Petitions Committee.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What are rights in the UK?', 'Entitlements protected by law, such as freedom of speech, association and a fair trial, largely set out in the Human Rights Act 1998.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is the role of the Equality Act 2010?', 'It consolidated anti-discrimination law, protecting nine characteristics including age, race, sex and disability.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'How have civil liberties been in conflict with security?', 'E.g. anti-terror laws allowing detention without charge and surveillance powers (Investigatory Powers Act 2016).', 21),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is the role of pressure groups in promoting rights?', 'Groups like Liberty and Amnesty campaign, bring legal cases, and raise awareness to protect rights.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a political party?', 'An organised group of people with shared ideas who seek to win elections and form a government.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the functions of political parties?', 'Representation, policy formulation, recruitment of leaders, political participation and forming government.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'How are UK parties funded?', 'Membership fees, donations from individuals, businesses and trade unions, and state funding such as Short money.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is Cranborne money?', 'State funding for opposition parties in the House of Lords.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the arguments for state funding of parties?', 'It reduces the influence of wealthy donors, creates a level playing field, and allows parties to focus on policy.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the arguments against state funding of parties?', 'Taxpayers fund parties they oppose, it may favour established parties, and parties could lose touch with members.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is the role of the Electoral Commission?', 'It regulates party finance and elections, including donations and spending limits.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What were the key features of Thatcherism?', 'Free markets, privatisation, reducing trade union power, low taxes, and a strong state on law and order.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What was New Labour?', 'The rebranding of Labour under Blair: the Third Way, accepting markets while investing in public services.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the key ideas of the Liberal Democrats?', 'Constitutional reform (including PR), civil liberties, pro-Europeanism, and environmental protection.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a minor party?', 'A party with limited representation in Parliament, e.g. the Greens or Reform UK.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a nationalist party?', 'A party seeking greater autonomy or independence for a nation, e.g. the SNP or Plaid Cymru.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a multi-party system?', 'A system where more than two parties have a realistic chance of forming or influencing government.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a dominant-party system?', 'A system where one party wins power repeatedly for a long period.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'How did the 2010 election affect the party system?', 'It produced a hung parliament and a Conservative–Liberal Democrat coalition, the first since 1945.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What was the result of the 2024 general election?', 'Labour won a large majority (411 seats) on about 34% of the vote; the Conservatives fell to 121 seats; the Lib Dems won 72.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'How did Reform UK perform in 2024?', 'It won about 14% of the vote but only 5 seats, showing how FPTP penalises parties with evenly spread support.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is party leadership selection in the Conservative Party?', 'MPs narrow the candidates to two, then members vote in a ballot.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is party leadership selection in the Labour Party?', 'Candidates need nominations from MPs (and affiliates or CLPs), then members and registered supporters vote using a preferential system.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is the impact of party leaders on electoral success?', 'Leaders shape party image and media coverage; popular leaders (e.g. Blair in 1997) help, unpopular ones hinder.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a manifesto?', 'A document setting out a party''s policies and promises before an election.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is the Salisbury Convention?', 'The Lords do not block legislation promised in the governing party''s manifesto at second reading.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is First Past the Post?', 'A plurality system: the candidate with the most votes in each constituency wins, regardless of whether they have a majority.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the advantages of FPTP?', 'Simple, quick results, strong single-party governments, and a clear MP–constituency link.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the disadvantages of FPTP?', 'Disproportionate results, wasted votes, safe seats, and tactical voting.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a safe seat?', 'A constituency where one party has a large majority and is very likely to win.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a marginal seat?', 'A constituency where the winning party has a small majority, so it could change hands.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is tactical voting?', 'Voting for a less preferred candidate to prevent a disliked candidate from winning.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a wasted vote?', 'A vote that doesn''t contribute to electing a candidate, e.g. votes for losing candidates or surplus votes for winners.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is the Supplementary Vote?', 'Voters mark first and second preferences; if no candidate gets 50%, the top two remain and second preferences are counted. It was used for mayors and PCCs until 2023.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Why was the Supplementary Vote replaced in England?', 'The Elections Act 2022 switched mayoral and PCC elections to FPTP.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is STV?', 'The Single Transferable Vote: voters rank candidates in multi-member constituencies, and candidates reaching a quota are elected, with surplus and eliminated votes transferred.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Where is AMS used in the UK?', 'The Scottish Parliament, the Senedd (until 2026) and the London Assembly.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'How is the Senedd electoral system changing?', 'From 2026 it uses a closed list PR system with larger multi-member constituencies and 96 members.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the advantages of AMS?', 'More proportional than FPTP while keeping constituency MPs, and voters get two votes.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the disadvantages of AMS?', 'Two classes of representative, closed party lists give parties control, and it often produces coalitions.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is the D''Hondt formula?', 'A method of allocating list seats: votes ÷ (seats already won + 1), used in AMS regional lists.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a coalition government?', 'A government formed by two or more parties, usually when no party has a majority.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a referendum?', 'A vote by the electorate on a single issue.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Give two examples of UK-wide referendums.', 'The 1975 EEC membership referendum, the 2011 AV referendum and the 2016 EU referendum.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What was the result of the 2016 EU referendum?', 'Leave won 51.9% to 48.1% on a 72.2% turnout.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the arguments for referendums?', 'They give legitimacy to major constitutional decisions and increase participation.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the arguments against referendums?', 'Complex issues are oversimplified, turnout can be low, and they undermine representative democracy.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Are UK referendums legally binding?', 'No; due to parliamentary sovereignty they are advisory, although politically very hard to ignore.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is class voting?', 'Voting based on social class, traditionally working class for Labour and middle class for the Conservatives.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is partisan dealignment?', 'The decline in strong, long-term identification with a political party.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is class dealignment?', 'The weakening link between social class and voting behaviour.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does age affect voting behaviour?', 'Older voters are more likely to vote Conservative and to turn out; younger voters lean Labour, Green or Lib Dem.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does education affect voting?', 'Graduates were more likely to vote Remain and Labour or Lib Dem in recent elections; non-graduates more likely to vote Leave and Conservative (2019).', 5),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does ethnicity affect voting?', 'Ethnic minority voters have historically been more likely to vote Labour, although this varies between groups.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does region affect voting?', 'Labour is strong in cities, Scotland (historically) and the North; the Conservatives in rural and southern England; the SNP has dominated Scotland since 2015.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is rational choice voting?', 'Voters make decisions based on their assessment of policies, performance and self-interest.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is issue voting?', 'Voting based on specific policy issues, such as Brexit or the economy.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the governing competence model?', 'Voters judge parties on their ability to govern effectively and manage the economy.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How did Black Wednesday (1992) affect voting?', 'It damaged the Conservatives'' reputation for economic competence, contributing to their 1997 defeat.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the significance of the 2017 election?', 'Theresa May lost her majority, forming a confidence-and-supply agreement with the DUP; Labour gained among young voters.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the role of opinion polls?', 'They measure public opinion and may influence voting through bandwagon or underdog effects.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'Should opinion polls be banned before elections?', 'Arguments for: they can influence voters and were inaccurate (e.g. 2015). Against: freedom of speech and they inform tactical voting.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the role of the media in elections?', 'It informs voters, sets agendas, and can shape perceptions of leaders and parties.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is media bias?', 'Media coverage that favours one party or viewpoint, most notable in UK newspapers.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'Is UK broadcasting required to be impartial?', 'Yes; Ofcom requires broadcasters to maintain due impartiality, unlike newspapers.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the influence of social media on voting?', 'It allows targeted campaigning, spreads information quickly, and may create echo chambers and misinformation.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the ''Sun wot won it''?', 'The Sun''s claim that its support helped the Conservatives win in 1992, although evidence of media effects is contested.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the significance of the 2019 election''s ''Red Wall''?', 'The Conservatives won many traditionally Labour seats in the North and Midlands, reflecting Brexit and dealignment.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the significance of the 2024 election for voting behaviour?', 'Very high volatility, a record low combined Labour–Conservative vote share, and big gains for Reform UK, the Lib Dems and Greens.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the importance of campaigns in elections?', 'Campaigns can shift votes through leaders'' debates, events and gaffes, especially with more volatile voters.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is traditional conservatism?', 'A conservatism that values tradition, hierarchy, organic society and gradual change, based on Burke.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is paternalism?', 'The idea that those with power and wealth have a duty to look after those less fortunate (noblesse oblige).', 2),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the organic society?', 'Society is like a living organism, with interdependent parts, which develops naturally over time.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is pragmatism in conservatism?', 'Making decisions based on practical circumstances rather than abstract principles or ideology.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is conservatism''s view of human nature?', 'Humans are imperfect: morally, intellectually and psychologically, so need order and authority.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is One Nation conservatism?', 'Disraeli''s idea that society is united and the wealthy have a duty to help the poor, to prevent social division.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the New Right?', 'A combination of neoliberalism (free markets) and neoconservatism (social order and authority).', 7),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is neoliberalism?', 'An ideology supporting free markets, deregulation, privatisation and a minimal state in the economy.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is neoconservatism?', 'An ideology stressing traditional values, law and order, national identity and a strong state.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is libertarianism?', 'An ideology prioritising individual liberty and a minimal state.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Hobbes''s view of the state of nature?', 'Life without government would be "nasty, brutish and short", so people accept a strong sovereign for security.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Burke''s view of change?', 'Change should be gradual and organic, preserving the wisdom of tradition, as opposed to revolution.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Oakeshott''s view of politics?', 'Politics should be pragmatic and based on experience, not rationalist blueprints or ideology.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Rand''s objectivism?', 'A philosophy that rational self-interest is moral and laissez-faire capitalism is the ideal system.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Nozick''s view of the state?', 'Only a minimal state protecting rights is justified; redistributive taxation violates self-ownership.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of property?', 'Property ownership gives security, encourages responsibility and respect for the law.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of the state?', 'The state should maintain order and authority; traditional conservatives accept intervention, the New Right wants a smaller state in the economy.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of the economy?', 'Traditional conservatives are pragmatic about intervention; neoliberals favour free markets.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is a tension between neoliberalism and neoconservatism?', 'Neoliberals want individual freedom and a small state; neoconservatives want a strong state enforcing social order and morality.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is authority in conservatism?', 'Authority comes from above and is natural and necessary to maintain order.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is hierarchy in conservatism?', 'Society is naturally hierarchical, with people in different positions performing different roles.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of human rationality?', 'Human reason is limited, so tradition and experience are better guides than abstract theory.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is individualism in liberalism?', 'The belief in the primacy of the individual over any social group or collective.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is classical liberalism?', 'Early liberalism emphasising individual freedom, a minimal state and free markets.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is modern liberalism?', 'Liberalism accepting that the state should intervene to enable individuals to achieve their potential (positive freedom).', 3),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the social contract?', 'The idea that the state''s authority rests on the consent of the governed.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Locke''s view of the state?', 'The state exists to protect natural rights to life, liberty and property, based on consent; people may rebel if it fails.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is limited government?', 'Government power restricted by a constitution, rights and the separation of powers.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is tolerance in liberalism?', 'Accepting views and lifestyles one disagrees with, as long as they don''t harm others.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of human nature?', 'Humans are rational and self-interested, but capable of reasoning and progress.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Mill''s view of liberty?', 'Individuals should be free to act as they wish, as long as they don''t harm others (the harm principle).', 9),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Wollstonecraft''s contribution to liberalism?', 'She argued women are rational beings entitled to the same rights and education as men.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Rawls''s theory of justice?', 'A just society is one people would choose behind a veil of ignorance, with equal liberties and inequalities only if they benefit the least well off.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Friedan''s contribution to liberalism?', 'She argued women were trapped in domestic roles ("the problem that has no name") and campaigned for legal equality.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of the economy?', 'Classical liberals support free markets; modern liberals support a mixed economy with state intervention (Keynesianism).', 13),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of society?', 'Society is a collection of individuals; modern liberals accept that social conditions affect individuals'' freedom.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is meritocracy?', 'A society where success is based on ability and effort rather than birth or privilege.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is liberal democracy?', 'A democracy with free elections, the rule of law, protection of rights and limited government.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the rule of law?', 'Everyone, including government, is subject to the law.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is equality of opportunity?', 'Everyone should have the same chance to succeed, regardless of background.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is foundational equality?', 'All humans are born with equal worth and rights.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is formal equality?', 'All individuals have the same legal and political rights.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of the state?', 'The state is a necessary evil (classical) or an enabler of freedom (modern).', 21),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'Why do liberals fear the tyranny of the majority?', 'Majorities may oppress minorities and limit individual freedom, so rights must be protected.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is collectivism?', 'The belief that collective action is more effective than individual action in achieving social and economic goals.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is common ownership?', 'Productive resources should be owned collectively, by the state or workers, rather than privately.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is social justice?', 'A fair distribution of wealth, opportunities and privileges in society.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is equality of outcome?', 'An equal distribution of wealth and resources, which socialists see as necessary for true equality.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of human nature?', 'Humans are social, cooperative and shaped by their environment.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is revolutionary socialism?', 'The belief that capitalism must be overthrown by revolution, e.g. Marxism.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is evolutionary socialism?', 'The belief that socialism can be achieved gradually through democratic means and reform.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is social democracy?', 'A form of socialism accepting a mixed economy and capitalism with welfare state intervention to reduce inequality.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the Third Way?', 'A revisionist approach combining market economics with social justice, associated with Giddens and New Labour.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Marx''s view of class?', 'Society is divided into the bourgeoisie (owners) and proletariat (workers), whose conflict drives history.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Webb''s contribution to socialism?', 'Beatrice Webb was a Fabian who argued socialism could be achieved gradually through reform and expertise.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Luxemburg''s view of socialism?', 'Capitalism must be overthrown by a mass revolutionary movement, but socialism must be democratic.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Crosland''s view of socialism?', 'Socialism is about equality and social justice, achievable within a mixed economy with welfare and education.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Giddens''s view of socialism?', 'The Third Way: accept globalisation and markets while investing in human capital and social inclusion.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of the state?', 'Revolutionary socialists see the state as a tool of class oppression; social democrats see it as a means to achieve reform.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of the economy?', 'The economy should be run for social needs rather than profit, through common ownership or regulation.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of society?', 'Society is shaped by class and economic structures; inequality is caused by capitalism.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is workers'' control?', 'The idea that workers should manage their workplaces democratically.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is cooperation in socialism?', 'Humans naturally work together for mutual benefit rather than competing.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is fraternity?', 'The bonds of comradeship and solidarity between people.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist critique of capitalism?', 'It is exploitative, creates inequality, alienation, and instability.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is alienation?', 'Marx''s idea that under capitalism workers are separated from the products of their labour, the process, each other and their humanity.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is a constitution?', 'A set of rules that establishes the structure and powers of government and the relationship between the state and citizens.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is an uncodified constitution?', 'A constitution not contained in a single document, drawn from several sources.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is an unentrenched constitution?', 'A constitution that can be changed by ordinary legislation, without special procedures.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is a unitary constitution?', 'Sovereignty lies with a central authority, which may delegate but not share power.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What are the sources of the UK constitution?', 'Statute law, common law, conventions, authoritative works and treaties.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is statute law?', 'Laws passed by Parliament, e.g. the Human Rights Act 1998.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is common law?', 'Law based on judicial decisions and precedent.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is a convention?', 'An unwritten rule that is followed by custom, e.g. the monarch gives royal assent to bills.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is an authoritative work?', 'A written text explaining how the constitution works, e.g. Bagehot''s The English Constitution or Erskine May.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the principle of parliamentary sovereignty?', 'Parliament can make or unmake any law, and no Parliament can bind its successors.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the rule of law in the UK constitution?', 'All are equal before the law, no one is above the law, and punishment only follows a breach of law.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Magna Carta (1215)?', 'A charter limiting royal power and establishing that the monarch is subject to the law.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Bill of Rights 1689?', 'It established parliamentary sovereignty over the monarch and rights such as free elections.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was devolution in 1998?', 'The transfer of powers from Westminster to a Scottish Parliament, a Welsh Assembly and a Northern Ireland Assembly.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Human Rights Act 1998?', 'It incorporated the European Convention on Human Rights into UK law.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the House of Lords Act 1999?', 'It removed all but 92 hereditary peers from the House of Lords.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Fixed-term Parliaments Act 2011?', 'It set five-year fixed terms and restricted early elections; it was repealed by the Dissolution and Calling of Parliament Act 2022.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the West Lothian Question?', 'Why Scottish MPs can vote on English-only matters while English MPs can''t vote on devolved Scottish matters.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was English Votes for English Laws (EVEL)?', 'A 2015 procedure giving English MPs a veto on England-only laws; it was abolished in 2021.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What are the arguments for a codified constitution?', 'Clarity, protection of rights, limits on government power, and education of citizens.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What are the arguments against a codified constitution?', 'Loss of flexibility, judges gaining political power, and difficulty agreeing on its content.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the Sewel Convention?', 'Westminster will not normally legislate on devolved matters without the consent of the devolved legislature.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the House of Commons?', 'The elected lower chamber of Parliament, with 650 MPs.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the House of Lords?', 'The unelected upper chamber, made up of life peers, hereditary peers and bishops.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the functions of Parliament?', 'Legislation, scrutiny of the executive, representation, and debate.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the legislative process in the UK?', 'First reading, second reading, committee stage, report stage, third reading, then the other House, and royal assent.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a Public Bill Committee?', 'A committee that examines bills line by line after second reading.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a select committee?', 'A committee that scrutinises government departments or policy areas.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is Prime Minister''s Questions?', 'A weekly session where MPs question the Prime Minister.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the role of the opposition?', 'To scrutinise and criticise the government and present itself as an alternative government.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is an Opposition Day?', 'Days (20 per session) when opposition parties choose the topics for debate.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the Backbench Business Committee?', 'Created in 2010, it schedules debates chosen by backbench MPs.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a Private Member''s Bill?', 'A bill introduced by a backbench MP or peer rather than the government.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a ten-minute rule bill?', 'A Private Member''s Bill introduced with a short speech, often used to raise awareness.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the role of the whips?', 'They maintain party discipline and ensure MPs vote with the party.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a backbench rebellion?', 'When MPs vote against their party''s position.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the role of MPs?', 'Representing constituents, scrutinising government, legislating and supporting their party.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the trustee model of representation?', 'MPs use their own judgement on behalf of constituents (Burke).', 16),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the delegate model of representation?', 'MPs act according to the wishes of their constituents.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the mandate model of representation?', 'MPs are elected to deliver the manifesto of their party.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the powers of the House of Lords?', 'It can delay most legislation for about a year, revise bills, scrutinise government and hold debates.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the arguments for an elected House of Lords?', 'Democratic legitimacy, accountability, and ending patronage.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the arguments against an elected House of Lords?', 'It could challenge the Commons, lose expertise, and create gridlock.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a life peer?', 'A member of the House of Lords appointed for life, whose title is not inherited.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the Cabinet?', 'The committee of senior ministers, chaired by the Prime Minister, that makes key decisions.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the Prime Minister?', 'The head of government, usually the leader of the largest party in the House of Commons.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What are the powers of the Prime Minister?', 'Appointing ministers, setting the agenda, controlling Cabinet, leading the party, and using the royal prerogative.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What are the constraints on the Prime Minister?', 'Size of majority, party unity, public opinion, events, Cabinet, and the media.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the core executive?', 'The network of institutions and people at the centre of government, including the PM, Cabinet, senior civil servants and advisers.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is a secondary legislation?', 'Rules made by ministers under powers granted by an Act of Parliament (statutory instruments).', 6),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the civil service?', 'Permanent, politically neutral officials who implement government policy.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is collective ministerial responsibility?', 'Ministers must publicly support all government decisions or resign.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is individual ministerial responsibility?', 'Ministers are responsible for their own conduct and the actions of their department.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Give an example of a resignation due to collective responsibility.', 'Robin Cook resigned in 2003 over the Iraq War.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Give an example of a resignation over personal conduct.', 'Matt Hancock resigned in 2021 after breaching COVID guidance.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is a Cabinet reshuffle?', 'When the Prime Minister changes the roles of ministers.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What are special advisers?', 'Political appointees who advise ministers and are not politically neutral, e.g. Dominic Cummings.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is prime ministerial government?', 'The view that the PM dominates the executive, rather than Cabinet.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is Cabinet government?', 'The view that decisions are made collectively by the Cabinet.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is presidentialism?', 'The idea that the UK PM has become more like a president, with personal mandates and dominance.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why did Thatcher fall in 1990?', 'Loss of Cabinet support, the poll tax, and divisions over Europe led to a leadership challenge.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why did Theresa May resign in 2019?', 'She failed to pass her Brexit withdrawal agreement and lost the support of her party.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why did Boris Johnson resign in 2022?', 'Scandals such as Partygate and the Pincher affair led to mass ministerial resignations.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why was Liz Truss''s premiership so short?', 'Her 2022 mini-budget caused market turmoil, destroying her authority; she resigned after 49 days.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the role of the Cabinet Office?', 'It supports the PM and Cabinet and coordinates government policy.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the royal prerogative?', 'Powers historically held by the monarch, now mostly exercised by ministers, e.g. treaty-making and deploying the armed forces.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the Supreme Court?', 'The highest court of appeal in the UK, established in 2009 to replace the Law Lords.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is judicial review?', 'The process by which courts review the lawfulness of decisions by public bodies.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is judicial independence?', 'Judges are free from political influence, e.g. security of tenure, salary protection and independent appointment.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is judicial neutrality?', 'Judges make decisions impartially, without personal bias.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'How are UK Supreme Court judges appointed?', 'By an independent selection commission, with the Lord Chancellor''s approval.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is a declaration of incompatibility?', 'A court ruling that a law is incompatible with the Human Rights Act; Parliament decides whether to change it.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is ultra vires?', 'Acting beyond legal authority.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'Give an example of a significant Supreme Court case on rights.', 'Belmarsh (2004, then Law Lords): detention of foreign terror suspects without trial was incompatible with human rights.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the Rwanda case (2023)?', 'The Supreme Court ruled that the Rwanda asylum plan was unlawful because of the risk of refoulement.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the relationship between Parliament and the executive?', 'The executive usually dominates Parliament through its majority, but Parliament scrutinises and can defeat government.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the relationship between the UK and the EU after Brexit?', 'The UK left in 2020, ending the supremacy of EU law and restoring parliamentary sovereignty over those areas.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the Factortame case (1990)?', 'The Law Lords disapplied an Act of Parliament that conflicted with EU law, showing EU law''s supremacy at the time.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is legal sovereignty?', 'The legal authority to make law, held by Parliament in the UK.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is political sovereignty?', 'Where political power actually lies, arguably with the electorate or the government.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is pooled sovereignty?', 'Sharing sovereignty with other states in international organisations, such as the EU.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the significance of the Miller (2017) case?', 'The government needed parliamentary approval to trigger Article 50.', 16),
