  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What are the weaknesses of the US Constitution?', 'Hard to amend, outdated provisions (e.g. the Second Amendment debate), and the Electoral College.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the role of the states?', 'States control many areas, e.g. education, criminal law and elections.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the significance of the Tenth Amendment?', 'Powers not given to the federal government are reserved to the states or the people.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'How has federal power grown?', 'Through the New Deal, the Great Society, the Commerce Clause, and responses to crises such as 9/11.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the House of Representatives?', 'The lower chamber of Congress, with 435 members elected every two years based on population.', 1),
