  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the power of the purse?', 'Congress controls taxation and spending.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the legislative process in the US?', 'Introduction, committee stage, floor debate and vote in both houses, a conference committee if needed, and presidential approval or veto.', 5),
